-- Hittites
insert or replace into LocalizedText (Language, Tag, Text) values
("en_US", "LOC_CIVINFO_MER_HITTITES_LOCATION", "The Hittites"),
("zh_Hans_CN", "LOC_CIVINFO_MER_HITTITES_LOCATION", "赫梯"),
("en_US", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_MER_HITTITES_CHAPTER_HISTORY_PARA_1", "The Hittites were an Anatolian people who played an important role in establishing an empire centered on Hattusa in north-central Anatolia around 1680-1650 BCE. This empire reached its height during the mid-14th century BC under Šuppiluliuma I, when it encompassed an area that included most of Anatolia as well as parts of the northern Levant and Upper Mesopotamia."),
("zh_Hans_CN", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_MER_HITTITES_CHAPTER_HISTORY_PARA_1", "赫梯人是安纳托利亚的一个民族，在公元前1680-1650年左右以安纳托利亚中北部的哈图沙为中心建立的帝国。这个帝国在公元前14世纪中叶在苏庇路里乌玛一世的统治下达到了鼎盛。当时它所涵盖的地区包括安纳托利亚的大部分地区以及北黎凡特和上美索不达米亚的部分地区。"),
("en_US", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_MER_HITTITES_CHAPTER_HISTORY_PARA_2", "Between the 15th and 13th centuries BC, the Empire of Hattusa, conventionally called the Hittite Empire, came into conflict with the New Kingdom of Egypt, the Middle Assyrian Empire and the empire of the Mitanni for control of the Near East. The Middle Assyrian Empire eventually emerged as the dominant power and annexed much of the Hittite Empire, while the remainder was sacked by Phrygian newcomers to the region. After c. 1180 BC, during the Late Bronze Age collapse, the Hittites splintered into several independent Syro-Hittite states, some of which survived until the eighth century BC before succumbing to the Neo-Assyrian Empire."),
("zh_Hans_CN", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_MER_HITTITES_CHAPTER_HISTORY_PARA_2", "在公元前15至13世纪之间，哈图沙帝国（传统上称为赫梯帝国）与埃及新王国、中亚述帝国和米坦尼帝国为控制近东地区发生了冲突。中亚述帝国最终成为主导力量，并吞并了赫梯帝国的大部分地区，而其余的地区则被新进入该地区的弗里吉亚人洗劫。约公元前1180年后，在青铜时代晚期的崩溃中，赫梯人分裂成几个独立的小赫梯国家，其中一些国家在屈服于新亚述帝国之前一直生存到公元前8世纪。"),
("en_US", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_MER_HITTITES_CHAPTER_HISTORY_PARA_3", "The development of iron smelting was once attributed to the Hittites of Anatolia during the Late Bronze Age, with their success largely based on the advantages of a monopoly on ironworking at the time. But the view of such a 'Hittite monopoly' has come under scrutiny and is no longer a scholarly consensus. As part of the Late-Bronze-Age/Early-Iron-Age, the Late Bronze Age collapse saw the slow, comparatively continuous spread of iron-working technology in the region. While there are some iron objects from Bronze Age Anatolia, the number is comparable to iron objects found in Egypt and other places during the period; and only a small number of these objects are weapons. Hittites did not use smelted iron, but rather meteorites. The Hittite military made successful use of chariots."),
("zh_Hans_CN", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_MER_HITTITES_CHAPTER_HISTORY_PARA_3", "炼铁的发展曾经被归功于青铜时代晚期安纳托利亚的赫梯人，他们的成功主要是基于当时垄断炼铁业的优势。但这种“赫梯人垄断”的观点已经受到了审查，不再是学术界的共识。作为晚青铜时代/早铁器时代的一部分，晚青铜时代的崩溃见证了铁器加工技术在该地区缓慢、相对持续的传播。虽然青铜时代安纳托利亚有一些铁制品，但其数量与埃及和这一时期其他地方发现的铁制品相当；而且这些制品中只有少数是武器。赫梯人并不使用冶炼的铁，而是使用陨石。赫梯人的军队成功地使用了战车。"),
("en_US", "LOC_LOADING_INFO_LEADER_MER_SUPPILULIUMA", "Blessings to you, Suppiluliuma, King of the Hittites. May your lands grow fertile and abundment under the blessing of the sun, while your many chariots storm the lands of those who would oppose you. Under the watch of a thousand gods the Hittites will flourish through your guidance and rulership, and friend and foe will swear bond and oath to serve you, just as you vow to serve them. But those who would betray that contract will meet the sword."),
("zh_Hans_CN", "LOC_LOADING_INFO_LEADER_MER_SUPPILULIUMA", "祝福你， 苏庇路里乌玛，赫梯人的国王。愿你的土地在太阳的祝福下变得肥沃丰饶，同时你的众多战车冲向那些反对你的人的土地。在无数神灵的注视下，赫梯人将在你的指导和统治下蓬勃发展。朋友和敌人都将发誓为你服务，就像你发誓为他们服务一样。但那些背叛盟约的人将死于剑下。"),
("en_US", "LOC_AGENDA_MER_OATHTAKER_NAME", "Oathtaker"),
("zh_Hans_CN", "LOC_AGENDA_MER_OATHTAKER_NAME", "守誓者"),
("en_US", "LOC_AGENDA_MER_OATHTAKER_DESCRIPTION", "Likes Civilizations who form alliances or befriend city-states. Dislikes Civilizations that declare surprise wars and do not establish alliances."),
("zh_Hans_CN", "LOC_AGENDA_MER_OATHTAKER_DESCRIPTION", "喜欢那些结成联盟或与城邦交好的文明。不喜欢那些突然宣布战争和不建立联盟的文明。[NEWLINE]"),
("en_US", "LOC_DIPLO_KUDOS_LEADER_MER_SUPPILULIUMA_REASON_FRIENDS", "(You seek friendships and alliances.)"),
("zh_Hans_CN", "LOC_DIPLO_KUDOS_LEADER_MER_SUPPILULIUMA_REASON_FRIENDS", "（您追求友谊和同盟）"),
("en_US", "LOC_DIPLO_MODIFIER_MER_SUPPILULIUMA_OATHTAKER_FRIENDS", "Suppiluliuma I is happy to see you seek alliances and vassals."),
("zh_Hans_CN", "LOC_DIPLO_MODIFIER_MER_SUPPILULIUMA_OATHTAKER_FRIENDS", "苏庇路里乌玛很高兴看到你寻求联盟和附庸。"),
("en_US", "LOC_DIPLO_WARNING_LEADER_MER_SUPPILULIUMA_REASON_BACKSTAB", "(You are isolated and untrustworthy.)"),
("zh_Hans_CN", "LOC_DIPLO_WARNING_LEADER_MER_SUPPILULIUMA_REASON_BACKSTAB", "(你是孤立无援的，不值得信任。)"),
("en_US", "LOC_DIPLO_MODIFIER_MER_SUPPILULIUMA_OATHTAKER_BACKSTAB", "Suppiluliuma I thinks you lack alliances and trust."),
("zh_Hans_CN", "LOC_DIPLO_MODIFIER_MER_SUPPILULIUMA_OATHTAKER_BACKSTAB", "苏庇路里乌玛认为你缺乏盟友，不值得信任。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SUPPILULIUMA_TITLE", "Suppiluliuma I"),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SUPPILULIUMA_TITLE", "苏庇路里乌玛一世"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SUPPILULIUMA_SUBTITLE", "King of the Hittites"),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SUPPILULIUMA_SUBTITLE", "赫梯国王"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SUPPILULIUMA_QUOTE", "Concerning the fact that no blood has been spilled between us before: the blood spilled since between us is not right."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SUPPILULIUMA_QUOTE", "我们之间不曾流血，也不必流血。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SUPPILULIUMA_CHAPTER_HISTORY_PARA_1", "Suppiluliuma I was king of the Hittites (1344–1322 BC). He achieved fame as a great warrior and statesman, successfully challenging the then-dominant Egyptian Empire for control of the lands between the Mediterranean and the Euphrates."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SUPPILULIUMA_CHAPTER_HISTORY_PARA_1", "苏庇路里乌玛一世是赫梯人的国王（公元前1344-1322）。他以伟大的战士和政治家的身份闻名，成功地挑战了当时占统治地位的埃及帝国对地中海和幼发拉底河之间土地的控制。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SUPPILULIUMA_CHAPTER_HISTORY_PARA_2", "Suppiluliuma married a sister to the Hayasan king Hukkana, and his daughter Muwatti to Maskhuiluwa of the Arzawan state Mira. He also married a Babylonian princess and retook Arzawan territory as far as Hapalla. His most permanent victory was against the Mitanni kingdom, which he reduced to a client state under his son-in-law Shattiwazza. He was also a master builder of large stone structures decorated with stone reliefs. It was during his reign that concepts of the sacred nature of royal leaders developed. Suppiluliuma then took advantage of the tumultuous reign of the Pharaoh Akhenaten, and seized control of Egyptian territory in Syria, inciting many Egyptian vassals to revolt."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SUPPILULIUMA_CHAPTER_HISTORY_PARA_2", "苏庇路里乌玛一世把一个妹妹嫁给了哈亚萨国王胡坎那，把他的女儿穆瓦提嫁给了阿尔萨瓦的米拉（赫梯附庸国）的玛斯克辉鲁瓦。他还娶了一位巴比伦公主，并重新夺回了远至哈帕拉的阿尔萨瓦领土。他最持久的胜利是对米坦尼王国的胜利，他把米坦尼王国降为他女婿沙特瓦扎手下的一个附庸国家。他也是一位建造石质建筑的大师，用石质浮雕进行装饰。正是在他的统治时期，皇家领袖的神圣地位得到了提升。随后，苏庇路里乌玛一世利用法老埃赫那吞的统治动荡，夺取了埃及在叙利亚的领土控制权，煽动许多埃及的附庸造反。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SUPPILULIUMA_CHAPTER_HISTORY_PARA_3", "His success encouraged the widow (who is called Dakhamunzu in the annals) of the Egyptian king Nibhururiya (usually identified with Tutankhamun) to write to him, asking him to send one of his sons to be her husband and rule Egypt, since she had no heir and was on the verge of being forced to marry 'a servant', usually thought to be the Egyptian general Horemheb or her late husband's vizier Ay. Suppiluliuma dispatched an ambassador to Egypt to investigate; he reported that the situation was accurately described, and the king decided to take advantage of this windfall; unfortunately, Prince Zannanza died on the way, and the marriage alliance never was consummated. Angry letters were exchanged between Suppiluliuma and the Pharaoh Ay, who had assumed the Egyptian throne, over the circumstances of Zannanza's death."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SUPPILULIUMA_CHAPTER_HISTORY_PARA_3", "他成功说服埃及国王尼布鲁里亚（通常被称作图坦卡蒙）的寡妇（在年谱中被称为达卡蒙祖）写信给他，要求他派他的一个儿子做她的丈夫并统治埃及，因为她没有继承人，而且即将被迫嫁给“一个仆人”，通常认为是埃及将军霍雷姆赫布或她已故丈夫的维齐尔艾。苏庇路里乌玛派遣了一位大使前往埃及调查；他报告说情况描述得很准确，国王决定利用这笔意外之财；不幸的是，赞南匝王子死在了路上，婚姻联盟从未完成过。苏庇路里乌玛用信件就赞南匝的死亡对已经登上埃及王位的艾法老表达出愤怒之情。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SUPPILULIUMA_CHAPTER_HISTORY_PARA_4", "Suppililiuma was furious at this turn of events and unleashed his armies against Egypt's vassal states in Canaan and Northern Syria, capturing much territory. nfortunately, many of the Egyptian prisoners carried a plague which would eventually ravage the Hittite heartland and lead to the deaths of both Suppiluliuma I and his successor, Arnuwanda II."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SUPPILULIUMA_CHAPTER_HISTORY_PARA_4", "苏庇路里乌玛对这一事件非常愤怒，他发动军队攻打埃及在迦南和北叙利亚的附庸国，夺取了许多领土。不幸的是，许多埃及俘虏携带了瘟疫，最终肆虐赫梯人的心脏地带，导致苏庇路里乌玛一世和他的继任者阿尔努万达二世死亡。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SUPPILULIUMA_CHAPTER_HISTORY_PARA_5", "The Deeds of Suppiluliuma, compiled after his death by his son Mursili, is an important primary source for the king's reign. One of Suppiluliuma's letters, addressed to Akhenaten, was preserved in the Amarna letters (EA 41) archive at Akhetaten. It expresses his hope that the good relations which existed between Egypt and Hatti under Akhenaten's father (Amenhotep III) would continue into Akhenaten's new reign."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SUPPILULIUMA_CHAPTER_HISTORY_PARA_5", "苏庇路里乌玛死后由其儿子穆尔西里编撰的《苏庇路里乌玛的事迹》是该国王统治时期的一个重要原始资料。苏庇路里乌玛写给埃赫那吞的一封信被保存在埃赫那吞的阿玛那信件（EA 41）档案中。信中表达了他希望在埃赫那吞的父亲（阿蒙霍特普三世）时期埃及和哈梯之间存在的良好关系能够延续到埃赫那吞的新统治中。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SUPPILULIUMA_CHAPTER_CAPSULE_BODY", "The Hittites focus on city-state and civilization diplomacy."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SUPPILULIUMA_CHAPTER_CAPSULE_BODY", "赫梯致力于城邦和文明外交。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SUPPILULIUMA_CHAPTER_DETAILED_BODY", "Suppiluliuma I is a warmongering leader of the Hittites with bonuses awarded for conquering cities."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SUPPILULIUMA_CHAPTER_DETAILED_BODY", "苏庇路里乌玛一世是赫梯的一个好战的领导人，征服城市可以获得产出。"),
("en_US", "LOC_DIPLO_FIRST_MEET_LEADER_MER_SUPPILULIUMA_ANY", "Greetings to you, I am Suppiluliuma I, I speak with the gods, and for the Hittites and all those who swear their bond to me."),
("zh_Hans_CN", "LOC_DIPLO_FIRST_MEET_LEADER_MER_SUPPILULIUMA_ANY", "向您问好，我是苏庇路里乌玛，我与众神对话，并为赫梯人和所有向我宣誓的人说话。"),
("en_US", "LOC_DIPLO_FIRST_MEET_VISIT_RECIPIENT_LEADER_MER_SUPPILULIUMA_ANY", "I'd like to invite you to visit Hattusa, the archivists will make note of this meetings."),
("zh_Hans_CN", "LOC_DIPLO_FIRST_MEET_VISIT_RECIPIENT_LEADER_MER_SUPPILULIUMA_ANY", "我想邀请你访问哈图沙，皇家档案员会记载这次会晤。"),
("en_US", "LOC_DIPLO_FIRST_MEET_NEAR_INITIATOR_POSITIVE_LEADER_MER_SUPPILULIUMA_ANY", "Thank you! We'll celebrate this day."),
("zh_Hans_CN", "LOC_DIPLO_FIRST_MEET_NEAR_INITIATOR_POSITIVE_LEADER_MER_SUPPILULIUMA_ANY", "谢谢！我们将庆祝这一天。"),
("en_US", "LOC_DIPLO_FIRST_MEET_NO_MANS_INFO_EXCHANGE_LEADER_MER_SUPPILULIUMA_ANY", "We should exchange records of our capital's locations."),
("zh_Hans_CN", "LOC_DIPLO_FIRST_MEET_NO_MANS_INFO_EXCHANGE_LEADER_MER_SUPPILULIUMA_ANY", "我们应该交换关于首都位置的纪录。"),
("en_US", "LOC_DIPLO_GREETING_LEADER_MER_SUPPILULIUMA_ANY", "Hello there."),
("zh_Hans_CN", "LOC_DIPLO_GREETING_LEADER_MER_SUPPILULIUMA_ANY", "你好。"),
("en_US", "LOC_DIPLO_ACCEPT_DELEGATION_FROM_HUMAN_LEADER_MER_SUPPILULIUMA_ANY", "Your delegation is gratefully received."),
("zh_Hans_CN", "LOC_DIPLO_ACCEPT_DELEGATION_FROM_HUMAN_LEADER_MER_SUPPILULIUMA_ANY", "衷心欢迎你们的代表团。"),
("en_US", "LOC_DIPLO_REJECT_DELEGATION_FROM_HUMAN_LEADER_MER_SUPPILULIUMA_ANY", "Sorry, we can't accept a delegation from you."),
("zh_Hans_CN", "LOC_DIPLO_REJECT_DELEGATION_FROM_HUMAN_LEADER_MER_SUPPILULIUMA_ANY", "对不起，我们不能接受你的代表团。[NEWLINE][NEWLINE]"),
("en_US", "LOC_DIPLO_DELEGATION_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "I have sent a delegation carrying finely crafted ivory figures and silverware, you can display them with pride that you received such a gift from me."),
("zh_Hans_CN", "LOC_DIPLO_DELEGATION_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "我已经派出一个代表团，带着精巧的象牙雕和银器，你可以自豪地展示它们，你从我这里收到了这样的礼物。"),
("en_US", "LOC_DIPLO_ACCEPT_OPEN_BORDERS_FROM_HUMAN_LEADER_MER_SUPPILULIUMA_ANY", "These terms are good."),
("zh_Hans_CN", "LOC_DIPLO_ACCEPT_OPEN_BORDERS_FROM_HUMAN_LEADER_MER_SUPPILULIUMA_ANY", "很好的条件。"),
("en_US", "LOC_DIPLO_REJECT_OPEN_BORDERS_FROM_HUMAN_LEADER_MER_SUPPILULIUMA_ANY", "Not today, perhaps another time."),
("zh_Hans_CN", "LOC_DIPLO_REJECT_OPEN_BORDERS_FROM_HUMAN_LEADER_MER_SUPPILULIUMA_ANY", "今天不行，或许改天吧。"),
("en_US", "LOC_DIPLO_OPEN_BORDERS_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "I'd like to present a binding oath to open borders."),
("zh_Hans_CN", "LOC_DIPLO_OPEN_BORDERS_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "我愿意开放边界立下一个坚定的誓言。"),
("en_US", "LOC_DIPLO_ACCEPT_DECLARE_FRIEND_FROM_HUMAN_LEADER_MER_SUPPILULIUMA_ANY", "A contract shall be written up immediatley."),
("zh_Hans_CN", "LOC_DIPLO_ACCEPT_DECLARE_FRIEND_FROM_HUMAN_LEADER_MER_SUPPILULIUMA_ANY", "应立即写好合约。"),
("en_US", "LOC_DIPLO_REJECT_DECLARE_FRIEND_FROM_HUMAN_LEADER_MER_SUPPILULIUMA_ANY", "Perhaps another time."),
("zh_Hans_CN", "LOC_DIPLO_REJECT_DECLARE_FRIEND_FROM_HUMAN_LEADER_MER_SUPPILULIUMA_ANY", "改天吧。"),
("en_US", "LOC_DIPLO_DECLARE_FRIEND_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "I present to you a written contract outlining a future friendship between our kingdoms."),
("zh_Hans_CN", "LOC_DIPLO_DECLARE_FRIEND_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "我向你提交一份书面合约，概述了我们王国之间未来的友谊。"),
("en_US", "LOC_DIPLO_ACCEPT_DECLARE_FRIEND_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "I swear to upload this deal."),
("zh_Hans_CN", "LOC_DIPLO_ACCEPT_DECLARE_FRIEND_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "我发誓要履行这笔交易。"),
("en_US", "LOC_DIPLO_REJECT_DECLARE_FRIEND_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "Perhaps the offer was not good enough?"),
("zh_Hans_CN", "LOC_DIPLO_REJECT_DECLARE_FRIEND_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "或许这个提议还不够好。"),
("en_US", "LOC_DIPLO_MAKE_ALLIANCE_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "If we both take oaths before the gods then we can forge a lasting alliance that can never be broken, or else plagues be brought upon our lands."),
("zh_Hans_CN", "LOC_DIPLO_MAKE_ALLIANCE_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "如果我们都在诸神面前宣誓，那么我们就可以建立一个持久的联盟，永远不会被打破，否则就会给我们的土地带来瘟疫。"),
("en_US", "LOC_DIPLO_KUDO_EXIT_LEADER_MER_SUPPILULIUMA_ANY", "You surround yourself with many friends and allies, all of which swear themselves to you, and you to them. It is the honourable way."),
("zh_Hans_CN", "LOC_DIPLO_KUDO_EXIT_LEADER_MER_SUPPILULIUMA_ANY", "你周围有许多朋友和盟友，他们都向你发誓，你也向他们发誓。这很体面。"),
("en_US", "LOC_DIPLO_WARNING_EXIT_LEADER_MER_SUPPILULIUMA_ANY", "Do you lack honour, oathbreaker? you isolate yourself from others and think only of yourself."),
("zh_Hans_CN", "LOC_DIPLO_WARNING_EXIT_LEADER_MER_SUPPILULIUMA_ANY", "你缺乏荣誉感吗，破誓者？你把自己与他人隔离开来，只想着自己。"),
("en_US", "LOC_DIPLO_WARNING_TOO_MANY_TROOPS_NEAR_ME_LEADER_MER_SUPPILULIUMA_ANY", "Move from my lands or face punishment from gods."),
("zh_Hans_CN", "LOC_DIPLO_WARNING_TOO_MANY_TROOPS_NEAR_ME_LEADER_MER_SUPPILULIUMA_ANY", "离开我的土地，否则你将面临神明的惩罚。"),
("en_US", "LOC_DIPLO_ACCEPT_MAKE_DEAL_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "Yes, i'll have the scribes write up a contract."),
("zh_Hans_CN", "LOC_DIPLO_ACCEPT_MAKE_DEAL_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "是的，我会让文士们写一份合约。"),
("en_US", "LOC_DIPLO_REJECT_MAKE_DEAL_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "Bah, a waste of time!"),
("zh_Hans_CN", "LOC_DIPLO_REJECT_MAKE_DEAL_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "真是浪费时间。"),
("en_US", "LOC_DIPLO_DENOUNCE_FROM_HUMAN_LEADER_MER_SUPPILULIUMA_ANY", "Would it be you were more willing that a lasting alliance between us could of been possible... but i see now that you would no doubt break any contract offered to you."),
("zh_Hans_CN", "LOC_DIPLO_DENOUNCE_FROM_HUMAN_LEADER_MER_SUPPILULIUMA_ANY", "如果你更愿意，我们之间可能会有一个持久的联盟......但我现在看到，你无疑会破坏提供给你的任何合约。"),
("en_US", "LOC_DIPLO_DENOUNCE_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "You are a worthless ruler, without faith, and without wisdom. (Denounces You)."),
("zh_Hans_CN", "LOC_DIPLO_DENOUNCE_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "你是一个无能的统治者，没有信仰，没有智慧。(谴责你）"),
("en_US", "LOC_DIPLO_DECLARE_WAR_FROM_HUMAN_LEADER_MER_SUPPILULIUMA_ANY", "You shall be trampled under the weight of our chariots."),
("zh_Hans_CN", "LOC_DIPLO_DECLARE_WAR_FROM_HUMAN_LEADER_MER_SUPPILULIUMA_ANY", "你必被我们战车重压践踏。"),
("en_US", "LOC_DIPLO_DECLARE_WAR_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "You have drawn the ire of the thousand gods and shall face their fury by my hand."),
("zh_Hans_CN", "LOC_DIPLO_DECLARE_WAR_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "你已经引起了千神的愤怒，并将在我手中面对他们的怒火。"),
("en_US", "LOC_DIPLO_MAKE_PEACE_AI_ACCEPT_DEAL_LEADER_MER_SUPPILULIUMA_ANY", "I accept these terms."),
("zh_Hans_CN", "LOC_DIPLO_MAKE_PEACE_AI_ACCEPT_DEAL_LEADER_MER_SUPPILULIUMA_ANY", "我接受这些条款。"),
("en_US", "LOC_DIPLO_MAKE_PEACE_AI_REFUSE_DEAL_LEADER_MER_SUPPILULIUMA_ANY", "This contract is unfair and twisted."),
("zh_Hans_CN", "LOC_DIPLO_MAKE_PEACE_AI_REFUSE_DEAL_LEADER_MER_SUPPILULIUMA_ANY", "这个合约扭曲且不公平。"),
("en_US", "LOC_DIPLO_MAKE_PEACE_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "This contract for peace should be more then fair, should you agree to take it."),
("zh_Hans_CN", "LOC_DIPLO_MAKE_PEACE_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "如果你同意接受，这份和约应该是比较公平的。"),
("en_US", "LOC_DIPLO_DEFEAT_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "I know my legacy shall be carried on in the words written by my people, that my name will live on in the annals of history."),
("zh_Hans_CN", "LOC_DIPLO_DEFEAT_FROM_AI_LEADER_MER_SUPPILULIUMA_ANY", "我知道我的遗产将在我的人民所写的文字中得到延续，我的名字将活在历史的长河中。"),
("en_US", "LOC_DIPLO_DEFEAT_FROM_HUMAN_LEADER_MER_SUPPILULIUMA_ANY", "You need not worry, we will write of this day, and my great victory. In that way, you will not be forgotten."),
("zh_Hans_CN", "LOC_DIPLO_DEFEAT_FROM_HUMAN_LEADER_MER_SUPPILULIUMA_ANY", "你不必担心，我们会写下这一天，以及我的伟大胜利。这样，你就不会被遗忘。"),
