-- Pacal
insert or replace into LocalizedText (Language, Tag, Text) values
("en_US", "LOC_AGENDA_LEU_PACAL_NAME", "Popol Vuh"),
("zh_Hans_CN", "LOC_AGENDA_LEU_PACAL_NAME", "《波波武经》"),
("en_US", "LOC_AGENDA_LEU_PACAL_DESCRIPTION", "Respects civilizations that heed the times and manage to enter a Golden Age when a new Era arrives. Dislikes Civilizations that regardless of having many World Wonders enter Dark Ages."),
("zh_Hans_CN", "LOC_AGENDA_LEU_PACAL_DESCRIPTION", "尊重那些顺应时代发展，在新时代到来时设法进入黄金时代的文明。不喜欢那些无论拥有多少世界奇迹都进入黑暗时代的文明。"),
("en_US", "LOC_DIPLO_MODIFIER_LEU_PACAL_POSITIVE", "Pacal likes civilizations that enter Golden Ages"),
("zh_Hans_CN", "LOC_DIPLO_MODIFIER_LEU_PACAL_POSITIVE", "帕卡尔喜欢进入黄金时代的文明。"),
("en_US", "LOC_DIPLO_KUDO_EXIT_LEADER_LEU_PACAL_ANY", "Ah, it seems you have listened to your forebearers, as this new cycle is bringing you prosperity. May our glory trascend this and all ages."),
("zh_Hans_CN", "LOC_DIPLO_KUDO_EXIT_LEADER_LEU_PACAL_ANY", "啊，看来你听从了你的先人，这个新的周期给你带来了繁荣。愿我们的荣耀超越这个时代，甚至是所有时代。"),
("en_US", "LOC_DIPLO_KUDO_LEADER_LEU_PACAL_REASON_ANY", "(You are in a Golden Age)"),
("zh_Hans_CN", "LOC_DIPLO_KUDO_LEADER_LEU_PACAL_REASON_ANY", "（你进入了黄金时代）"),
("en_US", "LOC_DIPLO_MODIFIER_LEU_PACAL_NEGATIVE", "Pacal dislikes civilizations that have too many Wonders while in a Dark Age"),
("zh_Hans_CN", "LOC_DIPLO_MODIFIER_LEU_PACAL_NEGATIVE", "帕卡尔不喜欢那些在黑暗时代中还拥有很多奇观的文明。"),
("en_US", "LOC_DIPLO_WARNING_EXIT_LEADER_LEU_PACAL_ANY", "I wonder. Do you dishonour your forebearers labor with how you languish now, or do you doom your children to languish later?"),
("zh_Hans_CN", "LOC_DIPLO_WARNING_EXIT_LEADER_LEU_PACAL_ANY", "我想知道你的怠惰是为了让先人蒙羞，还是为了让后嗣在怠惰中煎熬？"),
("en_US", "LOC_DIPLO_WARNING_LEADER_LEU_PACAL_REASON_ANY", "(You have too many Wonders and fell into a Dark Age)"),
("zh_Hans_CN", "LOC_DIPLO_WARNING_LEADER_LEU_PACAL_REASON_ANY", "（你在黑暗时代中还拥有很多奇观）"),
("en_US", "LOC_DIPLO_FIRST_MEET_LEADER_LEU_PACAL_ANY", "Ah, yes. My astronomers saw the portents of your arrival. You may call me Sun Shield, welcome to the majestic city of Palenque, will you visit the House of the Nine Sharpened Spears?"),
("zh_Hans_CN", "LOC_DIPLO_FIRST_MEET_LEADER_LEU_PACAL_ANY", "啊，是啊。我的占星术士们看到了你到来的预兆。你可以称我为太阳之盾。欢迎来到雄伟的帕伦克，你愿意参观“九矛之家”大神庙吗？"),
("en_US", "LOC_DIPLO_FIRST_MEET_VISIT_RECIPIENT_LEADER_LEU_PACAL_ANY", "There is no better place to watch the stars than our esteemed observatories. Come and gaze the skies!"),
("zh_Hans_CN", "LOC_DIPLO_FIRST_MEET_VISIT_RECIPIENT_LEADER_LEU_PACAL_ANY", "世界上没有比我们宏伟的的天文台更好的观星台了。来吧，看看这辽阔的天空!"),
("en_US", "LOC_DIPLO_FIRST_MEET_NEAR_INITIATOR_POSITIVE_LEADER_LEU_PACAL_ANY", "The Evening Star said that you'd agree, and it is always right."),
("zh_Hans_CN", "LOC_DIPLO_FIRST_MEET_NEAR_INITIATOR_POSITIVE_LEADER_LEU_PACAL_ANY", "长庚星认为你会同意的。祂从不出错。"),
("en_US", "LOC_DIPLO_FIRST_MEET_NO_MANS_INFO_EXCHANGE_LEADER_LEU_PACAL_ANY", "You have seen my cities, but not yet the greatest of them. Let us remedy this! Come, see the Temples for the Triad of Palenque!"),
("zh_Hans_CN", "LOC_DIPLO_FIRST_MEET_NO_MANS_INFO_EXCHANGE_LEADER_LEU_PACAL_ANY", "你已经看到了我的一些城市，但还没有看到其中最伟大的。你最好弥补这个遗憾! 来吧，看看帕伦克的三重神庙吧!"),
("en_US", "LOC_DIPLO_DELEGATION_FROM_AI_LEADER_LEU_PACAL_ANY", "I've sent some of my astronomers to view the night sky from your lands and exchange our knowledge and sciences. Would you accept them?"),
("zh_Hans_CN", "LOC_DIPLO_DELEGATION_FROM_AI_LEADER_LEU_PACAL_ANY", "我计划派我的一些占星术士在你们的土地上观测夜空，并交流我们的知识和科技。你能接受他们吗？"),
("en_US", "LOC_DIPLO_ACCEPT_DELEGATION_FROM_HUMAN_LEADER_LEU_PACAL_ANY", "The stars tell me this is a wise arrangement."),
("zh_Hans_CN", "LOC_DIPLO_ACCEPT_DELEGATION_FROM_HUMAN_LEADER_LEU_PACAL_ANY", "星辰告诉我这是一个明智的安排。"),
("en_US", "LOC_DIPLO_REJECT_DELEGATION_FROM_HUMAN_LEADER_LEU_PACAL_ANY", "No, no, I'm afraid the stars aren't fortuitous for it. My apologies."),
("zh_Hans_CN", "LOC_DIPLO_REJECT_DELEGATION_FROM_HUMAN_LEADER_LEU_PACAL_ANY", "很不巧，星辰不同意。我很抱歉。"),
("en_US", "LOC_DIPLO_GREETING_LEADER_LEU_PACAL_ANY", "I hope Xaman Ek was kind to you on your journey here."),
("zh_Hans_CN", "LOC_DIPLO_GREETING_LEADER_LEU_PACAL_ANY", "我希望北极星神夏曼艾克对你的生命慷慨而仁慈"),
("en_US", "LOC_DIPLO_OPEN_BORDERS_FROM_AI_LEADER_LEU_PACAL_ANY", "Opening our borders would allow for knowledge to flow more freely between us. Perhaps you'd consider it?"),
("zh_Hans_CN", "LOC_DIPLO_OPEN_BORDERS_FROM_AI_LEADER_LEU_PACAL_ANY", "开放我们的边界将使知识在我们之间更自由地流动。能考虑一下吗？"),
("en_US", "LOC_DIPLO_ACCEPT_OPEN_BORDERS_FROM_HUMAN_LEADER_LEU_PACAL_ANY", "Share your wisdom with my people."),
("zh_Hans_CN", "LOC_DIPLO_ACCEPT_OPEN_BORDERS_FROM_HUMAN_LEADER_LEU_PACAL_ANY", "请与我的人民分享你的智慧。"),
("en_US", "LOC_DIPLO_REJECT_OPEN_BORDERS_FROM_HUMAN_LEADER_LEU_PACAL_ANY", "No, this is not what the portents say."),
("zh_Hans_CN", "LOC_DIPLO_REJECT_OPEN_BORDERS_FROM_HUMAN_LEADER_LEU_PACAL_ANY", "不，这不符合预兆。"),
("en_US", "LOC_DIPLO_OPEN_BORDERS_FROM_AI_LEADER_LEU_PACAL_ANY", "A fellow academic! I suggest we band together and aid eachother. Would you agree?"),
("zh_Hans_CN", "LOC_DIPLO_OPEN_BORDERS_FROM_AI_LEADER_LEU_PACAL_ANY", "您是我们学术上的朋友！我建议我们团结起来，互相帮助。你同意吗？"),
("en_US", "LOC_DIPLO_ACCEPT_DECLARE_FRIEND_FROM_HUMAN_LEADER_LEU_PACAL_ANY", "Finally, a friend in our quest for knowledge."),
("zh_Hans_CN", "LOC_DIPLO_ACCEPT_DECLARE_FRIEND_FROM_HUMAN_LEADER_LEU_PACAL_ANY", "最后，我们在寻求知识的过程中找到了一个朋友。"),
("en_US", "LOC_DIPLO_REJECT_DECLARE_FRIEND_FROM_HUMAN_LEADER_LEU_PACAL_ANY", "I'm afraid not. Do not let this be an impediment on your search for knowledge, though."),
("zh_Hans_CN", "LOC_DIPLO_REJECT_DECLARE_FRIEND_FROM_HUMAN_LEADER_LEU_PACAL_ANY", "恐怕不行。不过，不要让这成为你寻求知识的障碍。"),
("en_US", "LOC_DIPLO_DENOUNCE_FROM_HUMAN_LEADER_LEU_PACAL_ANY", "The prophecies said you were a brute. I hoped they were misread."),
("zh_Hans_CN", "LOC_DIPLO_DENOUNCE_FROM_HUMAN_LEADER_LEU_PACAL_ANY", "预言说你是个野蛮人。我希望这只是一个误会。"),
("en_US", "LOC_DIPLO_DENOUNCE_FROM_AI_LEADER_LEU_PACAL_ANY", "You are an unenlightened, stupid, barbaric oaf who is alien to the very notion of science! Now get out! (Denounces You)"),
("zh_Hans_CN", "LOC_DIPLO_DENOUNCE_FROM_AI_LEADER_LEU_PACAL_ANY", "你是一个未开化的、愚蠢的、野蛮的傻瓜，与开化的理念格格不入! 现在滚出去！(谴责你)"),
("en_US", "LOC_DIPLO_ACCEPT_MAKE_DEAL_FROM_AI_LEADER_LEU_PACAL_ANY", "The stars align."),
("zh_Hans_CN", "LOC_DIPLO_ACCEPT_MAKE_DEAL_FROM_AI_LEADER_LEU_PACAL_ANY", "我们如同群星济济一堂。"),
("en_US", "LOC_DIPLO_REJECT_MAKE_DEAL_FROM_AI_LEADER_LEU_PACAL_ANY", "This would be most unwise"),
("zh_Hans_CN", "LOC_DIPLO_REJECT_MAKE_DEAL_FROM_AI_LEADER_LEU_PACAL_ANY", "这是非常不明智的。"),
("en_US", "LOC_DIPLO_MAKE_ALLIANCE_FROM_AI_LEADER_LEU_PACAL_ANY", "The gods in the stars have told me that this is a wise offer. Have your own astronomers told you the same?"),
("zh_Hans_CN", "LOC_DIPLO_MAKE_ALLIANCE_FROM_AI_LEADER_LEU_PACAL_ANY", "星空中的诸神告诉我，这是一个明智的提议。你自己的占星术士是否也这样告诉你？"),
("en_US", "LOC_DIPLO_WARNING_TOO_MANY_TROOPS_NEAR_ME_LEADER_LEU_PACAL_ANY", "Some of the Mayan centaurs have noticed your presence at our borders. Proceed with caution, the will of the Mayan is stronger than you believe"),
("zh_Hans_CN", "LOC_DIPLO_WARNING_TOO_MANY_TROOPS_NEAR_ME_LEADER_LEU_PACAL_ANY", "一些玛雅斥候已经注意到你们在我们边界的存在。谨慎行事，玛雅人的意志比你想象的要强。"),
("en_US", "LOC_DIPLO_DECLARE_WAR_FROM_HUMAN_LEADER_LEU_PACAL_ANY", "You cannot possibly stand against us. Knowledge, construction, and prophecy are on our side!"),
("zh_Hans_CN", "LOC_DIPLO_DECLARE_WAR_FROM_HUMAN_LEADER_LEU_PACAL_ANY", "你无法对抗我们。知识、科技和预兆都站在我们这边！"),
("en_US", "LOC_DIPLO_DECLARE_WAR_FROM_AI_LEADER_LEU_PACAL_ANYY", "I strike you down now, to fulfill prophecy, and to raise your cities to levels you never could."),
("zh_Hans_CN", "LOC_DIPLO_DECLARE_WAR_FROM_AI_LEADER_LEU_PACAL_ANYY", "我现在打倒你，是为了实现预言。并且我还可以将你的城市和人民改善到你达不到的高度。"),
("en_US", "LOC_DIPLO_MAKE_PEACE_AI_ACCEPT_DEAL_LEADER_LEU_PACAL_ANY", "And so everything is fulfilled. Yes, it is time to return to peace."),
("zh_Hans_CN", "LOC_DIPLO_MAKE_PEACE_AI_ACCEPT_DEAL_LEADER_LEU_PACAL_ANY", "一切条件都满足了。是时候回归和平了。"),
("en_US", "LOC_DIPLO_MAKE_PEACE_AI_ACCEPT_DEAL_LEADER_LEU_PACAL_ANY", "I'm afraid the stars do not favour your proposal. Fiend."),
("zh_Hans_CN", "LOC_DIPLO_MAKE_PEACE_AI_ACCEPT_DEAL_LEADER_LEU_PACAL_ANY", "恐怕星辰并不赞成你的提议，恶魔。"),
("en_US", "LOC_DIPLO_MAKE_PEACE_FROM_AI_LEADER_LEU_PACAL_ANY", "Our blood has spilled the earth, it is time to look for guidance in the stars yet again and stop this violence."),
("zh_Hans_CN", "LOC_DIPLO_MAKE_PEACE_FROM_AI_LEADER_LEU_PACAL_ANY", "我们的鲜血已经洒遍大地，现在是时候再次在星辰中寻找指引，我们应该停止这种暴力。"),
("en_US", "LOC_DIPLO_DEFEAT_FROM_HUMAN_LEADER_LEU_PACAL_ANY", "I was right, as I always am. You could never hope to stand against us."),
("zh_Hans_CN", "LOC_DIPLO_DEFEAT_FROM_HUMAN_LEADER_LEU_PACAL_ANY", "我一贯是正确的。你永远不可能对抗我们。"),
("en_US", "LOC_DIPLO_DEFEAT_FROM_AI_LEADER_LEU_PACAL_ANY", "Have I forsaken the warnings of my ancestors? Have I not built monuments to the stars so they would guide me? It appears that this is my final cycle..."),
("zh_Hans_CN", "LOC_DIPLO_DEFEAT_FROM_AI_LEADER_LEU_PACAL_ANY", "我是否背弃了我祖先的教诲？难道我没有为星辰建立纪念碑，让它们来指引我吗？这似乎是我的最后一个周期......"),
("en_US", "LOC_LEADER_LEU_PACAL_NAME", "Pacal"),
("zh_Hans_CN", "LOC_LEADER_LEU_PACAL_NAME", "帕卡尔"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_LEU_PACAL_TITLE", "K'inich Janaab Pakal I"),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_LEU_PACAL_TITLE", "基尼奇·哈纳布·帕卡尔"),
("en_US", "PEDIA_LEADERS_PAGE_LEADER_LEU_PACAL_SUBTITLE", "Ajaw of Palenque"),
("zh_Hans_CN", "PEDIA_LEADERS_PAGE_LEADER_LEU_PACAL_SUBTITLE", "帕伦克君主"),
("en_US", "LOC_CITY_NAME_LEU_PACAL_01", "Palenque"),
("zh_Hans_CN", "LOC_CITY_NAME_LEU_PACAL_01", "帕伦克"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_LEU_PACAL_QUOTE", "If I destroy you, I destroy myself. If I honor you, I honor myself."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_LEU_PACAL_QUOTE", "如果我毁灭你，我就毁灭我自己。如果我尊重你，我就尊重我自己。"),
("en_US", "LOC_LOADING_INFO_LEADER_LEU_PACAL", "Your coming has been foretold, K'inich Janaab Pakal. It is you that shall be the right hand of Itzamna, and it is you who shall be the Sun's Shield! Have your astronomers observe the heavens, and watch Venus track across the sky. It shall tell you when it is most auspicious to build the great palaces that shall make Palenque the envy of all worlds. Prepare yourself, Ajaw Pakal, because it is time for you to claim a destiny written in the stars."),
("zh_Hans_CN", "LOC_LOADING_INFO_LEADER_LEU_PACAL", "你的到来已被预言，基尼奇·哈纳布·帕卡尔。你将成为伊萨姆纳的右手，你将成为太阳之盾! 让你的占星术士观察天象，观察金星在天空中的轨迹。它将告诉你什么时候是建立伟业的最佳时机，这将使帕伦克成为世界的中心。准备好，帕伦克之主，因为现在是用星辰撰写你的命运的时刻。"),
("en_US", "LOC_TRAIT_LEADER_LEU_PACAL_NAME", "K'atun of Prosperity"),
("zh_Hans_CN", "LOC_TRAIT_LEADER_LEU_PACAL_NAME", "卡盾之盛"),
("en_US", "LOC_STATUS_MESSAGE_PACAL_SCIENCE_AND_FAITH", "The new Bak'tun cycle has been welcomed from your wondrous temples providing you {1_Science} [ICON_SCIENCE] Science and {2_Faith} [ICON_FAITH] Faith!"),
("zh_Hans_CN", "LOC_STATUS_MESSAGE_PACAL_SCIENCE_AND_FAITH", "雄伟的寺庙开始庆祝新巴克盾周期的开始，为你们提供 {1_Science} [ICON_SCIENCE] 科技和 {2_Faith} [ICON_FAITH] 信仰。"),
("en_US", "LOC_STATUS_MESSAGE_PACAL_SCIENCE", "The new Bak'tun cycle has been welcomed from your wondrous temples providing you {1_Science} [ICON_SCIENCE] Science"),
("zh_Hans_CN", "LOC_STATUS_MESSAGE_PACAL_SCIENCE", "雄伟的寺庙开始庆祝新巴克盾周期的开始，为你们提供 {1_Science} [ICON_SCIENCE] 科技。"),
("en_US", "LOC_STATUS_MESSAGE_PACAL_FAITH", "The new Bak'tun cycle has been welcomed from your wondrous temples providing you {1_Faith} [ICON_FAITH]"),
("zh_Hans_CN", "LOC_STATUS_MESSAGE_PACAL_FAITH", "雄伟的寺庙开始庆祝新巴克盾周期的开始，为你们提供 {2_Faith} [ICON_FAITH] 信仰。"),
("en_US", "LOC_STATUS_MESSAGE_PACAL_WONDER_BUILT_SCIENCE_AND_FAITH", "The astronomical positioning of the {1_Wonder} Wonder provides you {2_Science} [ICON_SCIENCE] Science and {3_Faith} [ICON_FAITH] Faith!"),
("zh_Hans_CN", "LOC_STATUS_MESSAGE_PACAL_WONDER_BUILT_SCIENCE_AND_FAITH", " {1_Wonder} 奇观的天文定位为你提供 {2_Science} [ICON_SCIENCE] 科技和 {3_Faith} [ICON_FAITH] 信仰!"),
("en_US", "LOC_STATUS_MESSAGE_GOLDEN_AGE_PACAL_WONDER_BUILT_SCIENCE_AND_FAITH", "The astronomical positioning of the {1_Wonder} Wonder in this Golden Age provides you {2_Science} [ICON_SCIENCE] Science and {3_Faith} [ICON_FAITH] Faith!"),
("zh_Hans_CN", "LOC_STATUS_MESSAGE_GOLDEN_AGE_PACAL_WONDER_BUILT_SCIENCE_AND_FAITH", " {1_Wonder} 奇观的天文定位为你提供 {2_Science} [ICON_SCIENCE] 科技和 {3_Faith} [ICON_FAITH] 信仰!"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_LEU_PACAL_CHAPTER_CAPSULE_BODY", "Pacal provides a strong incentive for building wonders, specially when aiming at a Science Victory or a Religious Victory"),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_LEU_PACAL_CHAPTER_CAPSULE_BODY", "帕卡尔对建造奇迹有很大雄心，特别是在以科技胜利或宗教胜利为目标时。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_LEU_PACAL_CHAPTER_DETAILED_BODY", "When playing as Pacal as the leader of the Maya your main focus should be preparing the ground for your Wonders. Try getting an early Golden Age so your accumulated bonuses from Wonders increase exponentially!"),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_LEU_PACAL_CHAPTER_DETAILED_BODY", "当你扮演玛雅人的领袖怕卡呃呃时，你的主要重点应该是为你的奇观准备土地。试着在早期进入一个黄金时代，这样你从奇观中积累的加成就会成倍增加。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_LEU_PACAL_CHAPTER_HISTORY_PARA_1", "K'inich Janaab Pakal I, also known as Pacal, Pacal the Great, 8 Ahau and Sun Shield, (March, 603 - August, 683) was ajaw of the Maya city-state of Palenque in the Late Classic period of pre-Columbian Mesoamerican chronology. He acceded to the throne in July 615 and ruled until his death. During a reign of 68 years, the longest known regnal period in the history of the Americas, the 30th longest worldwide and longest until Frederick III in the 15th century, Pakal was responsible for the construction or extension of some of Palenque's most notable surviving inscriptions and monumental architecture."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_LEU_PACAL_CHAPTER_HISTORY_PARA_1", "基尼奇·哈纳布·帕卡尔，又称帕卡尔、帕卡尔大帝、八天之主神和太阳之盾，（603年3月-683年8月）是前殖民时代中美洲的古典时期晚期玛雅城邦帕伦克的君主。他于615年7月登上王位，一直统治到去世。他68年的统治期是美洲历史上已知的最长的统治期，是世界上第30个最长的统治期，也是15世纪弗雷德里克三世之前最长的统治期。帕卡尔建造或扩建了帕伦克现存的一些最著名的石碑和纪念性建筑。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_LEU_PACAL_CHAPTER_HISTORY_PARA_2", "Pakal ascended the throne at age 12 and lived to the age of 80.  He expanded Palenque's power in the western part of the Maya states and initiated a building program at his capital that produced some of Maya civilization's finest art and architecture.  In 626 Pakal married Ix Tz'akbu Ajaw who was born in Uxte'k'uh.  Tz'akbu Ajaw was a descendant of the Toktahn dynasty, the original dynasty of Palenque.  In 628, one of Pakal's officials, was captured by Piedras Negras.  Six days later Nuun Ujol Chaak, ajaw of Santa Elena, was captured and taken to Palenque.  Having been appointed ajaw at the age of twelve, Pakal's mother was a regent to him, over the years she slowly lost power.  In 659 Pakal captured six prisoners, One of them, Ahiin Chan Ahk, was from Pipa'.  In 663 another lord of Pipa' was killed by Pakal.  In 647 K'inich Janaab Pakal began his first construction project.  Of all Pakal's construction projects, perhaps the most accomplished is the Palace of Palenque.  The building was already in existence, but Pakal made it much larger than it was.  Pakal started his construction by adding monument rooms onto the old level of the building.  The monuments and text associated with K'inich Janaab Pakal I are: Oval Palace Tablet, Hieroglyphic Stairway, House C texts, Subterranean Thrones and Tableritos, Olvidado piers and sarcophagus texts."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_LEU_PACAL_CHAPTER_HISTORY_PARA_2", "帕卡尔12岁登基，活到80岁。  他扩大了帕伦克在玛雅国家西部的权力，并在他的首都进行了建筑规划，他的时代产生了玛雅文明最好的一批艺术和建筑。[NEWLINE]626年，帕卡尔与兹阿克布女王结婚，后者出生于乌斯特库。兹阿克布是帕伦克原王朝托科塔王朝的后裔。[NEWLINE]628年，帕卡尔的一名官员，被黑石城城邦抓住。六天后，波科·温尼克城邦的君主努恩·乌乔尔·恰克被俘，并被带到帕伦克。帕卡尔的母亲在12岁时就被任命为摄政，随着时间推移她的权力慢慢转交到帕卡尔手上。[NEWLINE]659年，帕卡尔俘虏了六名囚犯，其中一个叫阿希因·昌·阿克的人来自皮帕。[NEWLINE]663年，皮帕的另一个领主被帕卡尔杀死。647年，帕卡尔开始了他的第一个建筑项目。[NEWLINE]在帕卡尔的所有建设项目中，可能成就最大的是帕伦克宫殿。  这座建筑当时已经存在，但帕卡尔把它建设得比原来大得多。  帕卡而在建设之初就在建筑的旧平台上增加了新的纪念房间。  与帕卡尔有关的纪念碑和文字是：椭圆宫殿石碑，象形文字楼梯，C型文字屋，地下王座和一些桥墩和石棺铭文。");

-- Assyria
insert or replace into LocalizedText (Language, Tag, Text) values
("en_US", "LOC_CIVILIZATION_BOOM_ASSYRIA_NAME", "Assyria"),
("zh_Hans_CN", "LOC_CIVILIZATION_BOOM_ASSYRIA_NAME", "亚述"),
("en_US", "LOC_CIVILIZATION_BOOM_ASSYRIA_DESCRIPTION", "Assyrian Empire"),
("zh_Hans_CN", "LOC_CIVILIZATION_BOOM_ASSYRIA_DESCRIPTION", "亚述帝国"),
("en_US", "LOC_CIVILIZATION_BOOM_ASSYRIA_ADJECTIVE", "Assyrian"),
("zh_Hans_CN", "LOC_CIVILIZATION_BOOM_ASSYRIA_ADJECTIVE", "亚述的"),
("en_US", "LOC_LEADER_BOOM_ASHURBANIPAL_NAME", "Ashurbanipal"),
("zh_Hans_CN", "LOC_LEADER_BOOM_ASHURBANIPAL_NAME", "亚述巴尼拔"),
("en_US", "LOC_TRAIT_LEADER_BOOM_ASHURBANIPAL_NAME", "Treasures of Ninevah"),
("zh_Hans_CN", "LOC_TRAIT_LEADER_BOOM_ASHURBANIPAL_NAME", "尼尼微的宝藏"),
("en_US", "LOC_TRAIT_CIVILIZATION_BOOM_ASSYRIA_NAME", "Ruba'Um"),
("zh_Hans_CN", "LOC_TRAIT_CIVILIZATION_BOOM_ASSYRIA_NAME", "阿苏尔之子民"),
("en_US", "LOC_BOOM_IMPROVEMENT_LAMASSU_NAME", "Lamassu"),
("zh_Hans_CN", "LOC_BOOM_IMPROVEMENT_LAMASSU_NAME", "拉玛苏像"),
("en_US", "LOC_BOOM_UNIT_SIEGE_ENGINE_NAME", "Siege Engine"),
("zh_Hans_CN", "LOC_BOOM_UNIT_SIEGE_ENGINE_NAME", "攻城车"),
("en_US", "LOC_PROJECT_BOOM_MASS_RESETTLEMENT_NAME", "Mass Resettlement"),
("zh_Hans_CN", "LOC_PROJECT_BOOM_MASS_RESETTLEMENT_NAME", "大迁移"),
("en_US", "LOC_PROJECT_BOOM_MASS_RESETTLEMENT_DESCRIPTION", "When complete, this project transfers one [ICON_Citizen] Population from all captured cities within a 5 tile radius to this city. Grants free Roads around the city."),
("zh_Hans_CN", "LOC_PROJECT_BOOM_MASS_RESETTLEMENT_DESCRIPTION", "完成时，从5单元格内亚述征服的城市迁移一个人口至本城市。市中心周围获得道路"),
("en_US", "LOC_BUILDING_BOOM_ROYAL_LIBRARY_NAME", "Library of Ashurbanipal"),
("zh_Hans_CN", "LOC_BUILDING_BOOM_ROYAL_LIBRARY_NAME", "亚述巴尼拔图书馆"),
("en_US", "LOC_AGENDA_BOOM_ERUDITE_NAME", "Erudite"),
("zh_Hans_CN", "LOC_AGENDA_BOOM_ERUDITE_NAME", "智者"),
("en_US", "LOC_AGENDA_BOOM_ERUDITE_DESCRIPTION", "Likes civilizations who are less advanced than him. Dislikes civilizations who are more advanced than him or compete with him for Great Works of [ICON_GreatWork_Writing] Writing."),
("zh_Hans_CN", "LOC_AGENDA_BOOM_ERUDITE_DESCRIPTION", "喜欢比他落后的文明；不喜欢比他先进或者在著作巨作方面与其竞争的文明。"),
("en_US", "LOC_DIPLO_KUDO_EXIT_LEADER_BOOM_ASHURBANIPAL_ANY", "You understand that the strength and intelligence bestowed on me by the grace of gods is insurmountable. This is good."),
("zh_Hans_CN", "LOC_DIPLO_KUDO_EXIT_LEADER_BOOM_ASHURBANIPAL_ANY", "你明白诸神恩赐给我的力量和智慧是不可战胜的。这很好。"),
("en_US", "LOC_DIPLO_KUDO_LEADER_BOOM_ASHURBANIPAL_REASON_ANY", "(You are less advanced in science in culture)"),
("zh_Hans_CN", "LOC_DIPLO_KUDO_LEADER_BOOM_ASHURBANIPAL_REASON_ANY", "（你在文化和科技上比亚述落后）"),
("en_US", "LOC_DIPLO_MODIFIER_BOOM_ERUDITE_LAGGING", "You are weird"),
("zh_Hans_CN", "LOC_DIPLO_MODIFIER_BOOM_ERUDITE_LAGGING", "你很奇怪"),
("en_US", "LOC_DIPLO_ACCEPT_DECLARE_FRIEND_FROM_HUMAN_LEADER_BOOM_ASHURBANIPAL_ANY", "Very well. I shall bestow upon your people the wisdom and strength of Assyria."),
("zh_Hans_CN", "LOC_DIPLO_ACCEPT_DECLARE_FRIEND_FROM_HUMAN_LEADER_BOOM_ASHURBANIPAL_ANY", "很好。我将把亚述的智慧和力量赐给你的人民。"),
("en_US", "LOC_DIPLO_REJECT_DECLARE_FRIEND_FROM_HUMAN_LEADER_BOOM_ASHURBANIPAL_ANY", "Your presumption in acting as my equal astounds me. Pray that I do not take it as an insult."),
("zh_Hans_CN", "LOC_DIPLO_REJECT_DECLARE_FRIEND_FROM_HUMAN_LEADER_BOOM_ASHURBANIPAL_ANY", "令我震惊的是你妄想与我平起平坐。你最好祈祷我现在不将这愚行视为冒犯！"),
("en_US", "LOC_DIPLO_DECLARE_FRIEND_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "I offer you the cooperation of Assyria. Join me in the graces of Ashur!"),
("zh_Hans_CN", "LOC_DIPLO_DECLARE_FRIEND_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "亚述愿与你合作。在阿苏尔的恩典中加入我们吧。"),
("en_US", "LOC_DIPLO_ACCEPT_DECLARE_FRIEND_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "Very good, we stand as equals."),
("zh_Hans_CN", "LOC_DIPLO_ACCEPT_DECLARE_FRIEND_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "很好，我们将平起平坐。"),
("en_US", "LOC_DIPLO_REJECT_DECLARE_FRIEND_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "You would turn aside my generosity?"),
("zh_Hans_CN", "LOC_DIPLO_REJECT_DECLARE_FRIEND_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "你拒绝我的慷慨吗？"),
("en_US", "LOC_DIPLO_DECLARE_WAR_FROM_HUMAN_LEADER_BOOM_ASHURBANIPAL_ANY", "For this insolence, I will crush your people and grind your cities to dust."),
("zh_Hans_CN", "LOC_DIPLO_DECLARE_WAR_FROM_HUMAN_LEADER_BOOM_ASHURBANIPAL_ANY", "因为这种无礼行为，我将粉碎你的人民，将你的城市碾成尘土。"),
("en_US", "LOC_DIPLO_DECLARE_WAR_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "Ashur has granted me the strength and wisdom to raze your empire to the ground and make your people and knowledge my own."),
("zh_Hans_CN", "LOC_DIPLO_DECLARE_WAR_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "阿苏尔赐予我力量和智慧，我会将你的帝国夷为平地，占有你的人民和知识。"),
("en_US", "LOC_DIPLO_ACCEPT_DELEGATION_FROM_HUMAN_LEADER_BOOM_ASHURBANIPAL_ANY", "Your delegation shall return to you filled with wonder at the sights of Assyria and the splendor of the Royal Library."),
("zh_Hans_CN", "LOC_DIPLO_ACCEPT_DELEGATION_FROM_HUMAN_LEADER_BOOM_ASHURBANIPAL_ANY", "你的代表团返回后将向你讲述亚述风景之壮美与皇家图书馆之华丽。"),
("en_US", "LOC_DIPLO_REJECT_DELEGATION_FROM_HUMAN_LEADER_BOOM_ASHURBANIPAL_ANY", "Your filthy savage people shall not even deign to approach the wonders of the Assyrian Empire."),
("zh_Hans_CN", "LOC_DIPLO_REJECT_DELEGATION_FROM_HUMAN_LEADER_BOOM_ASHURBANIPAL_ANY", "你们这些肮脏的野蛮人不应妄图近亚述帝国的奇观。"),
("en_US", "LOC_DIPLO_DELEGATION_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "Assyria sends you kipteh and dokhwa, prepared by our royal chefs."),
("zh_Hans_CN", "LOC_DIPLO_DELEGATION_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "亚述给你送来了由我们的皇家厨师准备的肉丸汤和酸奶牛肉麦粥。"),
("en_US", "LOC_DIPLO_DENOUNCE_FROM_HUMAN_LEADER_BOOM_ASHURBANIPAL_ANY", "Your slander of me displays your woeful ignorance. Your foolish words mean nothing."),
("zh_Hans_CN", "LOC_DIPLO_DENOUNCE_FROM_HUMAN_LEADER_BOOM_ASHURBANIPAL_ANY", "你对我的诽谤显示了你可悲的无知。你愚蠢的话语毫无意义。"),
("en_US", "LOC_DIPLO_DENOUNCE_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "Your incompetence at ruling is exceeded only by your malice and stupidity. I seek only to destroy you. (Denounces You.)"),
("zh_Hans_CN", "LOC_DIPLO_DENOUNCE_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "你在统治方面的无能仅次于你的愚蠢和恶毒。我只想消灭你。(谴责你。）"),
("en_US", "LOC_DIPLO_FIRST_MEET_LEADER_BOOM_ASHURBANIPAL_ANY", "I am Ashurbanipal, king of the universe, whom the gods have bestowed with intelligence and strength. Are you afraid?"),
("zh_Hans_CN", "LOC_DIPLO_FIRST_MEET_LEADER_BOOM_ASHURBANIPAL_ANY", "我是亚述巴尼拔，宇宙之王，诸神赐予我智慧和力量。你害怕吗？"),
("en_US", "LOC_DIPLO_FIRST_MEET_VISIT_RECIPIENT_LEADER_BOOM_ASHURBANIPAL_ANY", "Assyria has prepared a glorious reception for you, shall you come see our capital?"),
("zh_Hans_CN", "LOC_DIPLO_FIRST_MEET_VISIT_RECIPIENT_LEADER_BOOM_ASHURBANIPAL_ANY", "亚述已经为你准备了一个盛大又光荣的接风仪式，你要不要来看看我们的首都？"),
("en_US", "LOC_DIPLO_FIRST_MEET_NEAR_INITIATOR_POSITIVE_LEADER_BOOM_ASHURBANIPAL_ANY", "Of course."),
("zh_Hans_CN", "LOC_DIPLO_FIRST_MEET_NEAR_INITIATOR_POSITIVE_LEADER_BOOM_ASHURBANIPAL_ANY", "当然。"),
("en_US", "LOC_DIPLO_FIRST_MEET_NO_MANS_INFO_EXCHANGE_LEADER_BOOM_ASHURBANIPAL_ANY", "I shall tell you of the great city of Ninevah and its grand library, if you will tell me of your cities."),
("zh_Hans_CN", "LOC_DIPLO_FIRST_MEET_NO_MANS_INFO_EXCHANGE_LEADER_BOOM_ASHURBANIPAL_ANY", "我将告诉你们伟大的尼尼微城和它的大图书馆，如果你们愿意告诉我你们的城市。"),
("en_US", "LOC_DIPLO_GREETING_LEADER_BOOM_ASHURBANIPAL_ANY", "Greetings again."),
("zh_Hans_CN", "LOC_DIPLO_GREETING_LEADER_BOOM_ASHURBANIPAL_ANY", "再次问好。"),
("en_US", "LOC_DIPLO_WARNING_EXIT_LEADER_BOOM_ASHURBANIPAL", "You would attempt to match the wisdom bestowed upon me by the gods? You are even more foolish than I assumed."),
("zh_Hans_CN", "LOC_DIPLO_WARNING_EXIT_LEADER_BOOM_ASHURBANIPAL", "你试图与诸神赋予我的智慧相提并论？你比我想象的还要愚蠢。"),
("en_US", "LOC_DIPLO_MAKE_ALLIANCE_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "Let us make an accord to unravel the secrets of the universe together."),
("zh_Hans_CN", "LOC_DIPLO_MAKE_ALLIANCE_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "让我们达成协议，一起解开宇宙的秘密。"),
("en_US", "LOC_DIPLO_MAKE_PEACE_AI_ACCEPT_DEAL_LEADER_BOOM_ASHURBANIPAL_ANY", "Assyria has taken what she requires from you. Let peace be had."),
("zh_Hans_CN", "LOC_DIPLO_MAKE_PEACE_AI_ACCEPT_DEAL_LEADER_BOOM_ASHURBANIPAL_ANY", "亚述已经从你们那里拿走了她所需要的东西。让我们和平相处吧。"),
("en_US", "LOC_DIPLO_MAKE_PEACE_AI_REFUSE_DEAL_LEADER_BOOM_ASHURBANIPAL_ANY", "This war shall not end until your people are corpses and your cities are dust."),
("zh_Hans_CN", "LOC_DIPLO_MAKE_PEACE_AI_REFUSE_DEAL_LEADER_BOOM_ASHURBANIPAL_ANY", "这场战争将不会结束，直到你的人民成为尸山，你的城市成为尘土。"),
("en_US", "LOC_DIPLO_MAKE_PEACE_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "Assyria is prepared to grant you mercy, if you would make peace."),
("zh_Hans_CN", "LOC_DIPLO_MAKE_PEACE_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "亚述准备给予你们仁慈，如果你们愿意讲和。"),
("en_US", "LOC_DIPLO_ACCEPT_OPEN_BORDERS_FROM_HUMAN_LEADER_BOOM_ASHURBANIPAL_ANY", "Very well, you may move through the lands of Ashur."),
("zh_Hans_CN", "LOC_DIPLO_ACCEPT_OPEN_BORDERS_FROM_HUMAN_LEADER_BOOM_ASHURBANIPAL_ANY", "很好，你可以在阿苏尔的土地上来往。"),
("en_US", "LOC_DIPLO_REJECT_OPEN_BORDERS_FROM_HUMAN_LEADER_BOOM_ASHURBANIPAL_ANY", "Your people shall not enter the lands of Ashur,"),
("zh_Hans_CN", "LOC_DIPLO_REJECT_OPEN_BORDERS_FROM_HUMAN_LEADER_BOOM_ASHURBANIPAL_ANY", "你的子民不可进入阿苏尔的土地。"),
("en_US", "LOC_DIPLO_OPEN_BORDERS_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "My armies have conquests to make, may we cross your land?"),
("zh_Hans_CN", "LOC_DIPLO_OPEN_BORDERS_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "我的军队要进行征服，我们可以穿过你的土地吗？"),
("en_US", "LOC_DIPLO_WARNING_TOO_MANY_TROOPS_NEAR_ME_LEADER_BOOM_ASHURBANIPAL_ANY", "Move your troops from my border at once, unless you wish to feel the full force of the Assyrian Empire"),
("zh_Hans_CN", "LOC_DIPLO_WARNING_TOO_MANY_TROOPS_NEAR_ME_LEADER_BOOM_ASHURBANIPAL_ANY", "立即将你的军队从我的边界转移走，除非你想感受亚述帝国的全部力量。"),
("en_US", "LOC_DIPLO_WARNING_TOO_MANY_TROOPS_NEAR_ME_AI_RESPONSE_NEGATIVE_LEADER_BOOM_ASHURBANIPAL_ANY", "No. My troop movements are necessary, you would not understand."),
("zh_Hans_CN", "LOC_DIPLO_WARNING_TOO_MANY_TROOPS_NEAR_ME_AI_RESPONSE_NEGATIVE_LEADER_BOOM_ASHURBANIPAL_ANY", "不，我的部队调动是必要的，你不会理解。"),
("en_US", "LOC_DIPLO_WARNING_TOO_MANY_TROOPS_NEAR_ME_AI_RESPONSE_POSITIVE_LEADER_BOOM_ASHURBANIPAL_ANY", "Very well, Assyria shall withdraw, for now."),
("zh_Hans_CN", "LOC_DIPLO_WARNING_TOO_MANY_TROOPS_NEAR_ME_AI_RESPONSE_POSITIVE_LEADER_BOOM_ASHURBANIPAL_ANY", "好，亚述将暂时退撤退。"),
("en_US", "LOC_DIPLO_DEFEAT_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "With cries of woe I bring my days to an end. On the day of the city god, the day of the festival, I am wretched; death is seizing hold upon me, and bears me down..."),
("zh_Hans_CN", "LOC_DIPLO_DEFEAT_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "我的时日在哀嚎中终结，在阿苏尔的节日中，我落得个悲惨下场。死亡压倒了我……"),
("en_US", "LOC_DIPLO_REJECT_MAKE_DEAL_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "This offer is an insult."),
("zh_Hans_CN", "LOC_DIPLO_REJECT_MAKE_DEAL_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "这个提议如图冒犯！"),
("en_US", "LOC_DIPLO_ACCEPT_MAKE_DEAL_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "Very well, this offer serves us both."),
("zh_Hans_CN", "LOC_DIPLO_ACCEPT_MAKE_DEAL_FROM_AI_LEADER_BOOM_ASHURBANIPAL_ANY", "很好，这个提议对我们双方都有利。"),
("en_US", "LOC_CIVINFO_BOOM_ASSYRIA_LOCATION", "Middle East"),
("zh_Hans_CN", "LOC_CIVINFO_BOOM_ASSYRIA_LOCATION", "中东"),
("en_US", "LOC_CIVINFO_BOOM_ASSYRIA_SIZE", "650,000 square miles (1.6 million square km)"),
("zh_Hans_CN", "LOC_CIVINFO_BOOM_ASSYRIA_SIZE", "650,000平方英里（160万平方公里）。"),
("en_US", "LOC_CIVINFO_BOOM_ASSYRIA_POPULATION", "Approximately 5 million at its peak"),
("zh_Hans_CN", "LOC_CIVINFO_BOOM_ASSYRIA_POPULATION", "最高峰时约为500万"),
("en_US", "LOC_CIVINFO_BOOM_ASSYRIA_CAPITAL", "Capital varied from ruler to ruler, kings often moved their capital."),
("zh_Hans_CN", "LOC_CIVINFO_BOOM_ASSYRIA_CAPITAL", "首都因统治者而异，国王们经常迁都。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_ASHURBANIPAL_QUOTE", "I reduced the temples of Elam to naught; their gods and goddesses I scattered to the winds. The tombs of their ancient and recent kings I devastated, I exposed to the sun, and I carried away their bones toward the land of Ashur. I devastated the provinces of Elam and on their lands I sowed salt."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_ASHURBANIPAL_QUOTE", "我使埃兰的庙宇化为乌有，将他们的神明毁灭于风中。我毁坏他们从古至今的国王的坟墓，挖出他们的尸骨，并运往阿苏尔的土地。我焚毁了埃兰的城市，在他们的土地上撒盐。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_BOOM_ASHURBANIPAL_CHAPTER_CAPSULE_BODY", "Ashurbanipal seeks to conquer nearby cities in order to gain new knowledge through the Great Writer points he earns and the accumulation of Great Works of Writing he receives."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_BOOM_ASHURBANIPAL_CHAPTER_CAPSULE_BODY", "亚述巴尼拔寻求征服附近的城市，以便他得新知识。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_BOOM_ASHURBANIPAL_CHAPTER_DETAILED_BODY", "As the largest and most powerful empire of the ancient Mesopotamian world, known for their strength in siegecraft and incorporating captured empires under their control, Assyria is able to quickly take down cities with the Siege Engine unit, and quickly make them productive with their bonus to infrastructure in those cities. Ashurbanipal utilizes Assyria's powerful conquest abilities in order to recruit [ICON_GreatWriter] Great Writers, which then allow him to leap ahead in the Technology and Civics trees"),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_BOOM_ASHURBANIPAL_CHAPTER_DETAILED_BODY", "作为古代美索不达米亚世界最大和最强大的帝国，亚述以其在攻城方面的实力和将俘获的人民纳入其控制之下而闻名，亚述能够利用攻城车迅速攻下城市，并通过对这些城市的基础设施的掠夺迅速使其成为生产力。亚述巴尼拔利用亚述强大的征服能力来招募伟人，然后让他在科技和文化树上取得飞跃。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_BOOM_ASHURBANIPAL_CHAPTER_HISTORY_PARA_1", "Ashurbanipal was born in 685BC, the fourth son to the Assyrian king Esarhaddon, and thus seemed destined to never become king, with three others in the line of succession before him. However, in 674BC, the unexpected death of Esarhaddon's eldest son threw the Assyrian court into chaos. Wishing to cement his succession, Esarheddon proclaimed his second son, Shamash-shum-ukin, the king of Babylon, and Ashurbanipal as the king of Assyria. This unexpected compromise allowed Ashurbanipal to rise to the head of Assyria in 669, during which time he cooperated with his sibling as 'equal brothers' in ruling."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_BOOM_ASHURBANIPAL_CHAPTER_HISTORY_PARA_1", "亚述巴尼拔生于公元前685年，是亚述国王阿萨哈东的第四个儿子，因此似乎注定无法成为国王，在他之前还有三个人在继承。然而，在公元前674年，阿萨哈东的长子意外死亡，使亚述宫廷陷入混乱。为了巩固自己的继承权，阿萨哈东宣布他的次子沙马什-舒姆-乌金为巴比伦国王，而亚述巴尼拔为亚述国王。这一意外的妥协使亚述巴尼拔在669年上升为亚述的首脑，在此期间，他与他的兄弟姐妹以“平等的兄弟”身份合作统治。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_BOOM_ASHURBANIPAL_CHAPTER_HISTORY_PARA_2", "Despite some fears of rebellion during his ascension to the throne, especially by his grandmother, who forced the lords of Assyria to swear fealty to Ashurbanipal, the change of power was peaceful. Shamash-shum-ukin was crowned a year later, but despite the wishes of their father that they remain 'equal brothers', Ashurbanipal intentionally drew power toward himself, demanding an oath of fealty from his brother. This grab at power foreshadowed the events of his rule"),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_BOOM_ASHURBANIPAL_CHAPTER_HISTORY_PARA_2", "尽管在他登基的过程中有些担心会发生叛乱，特别由于是他的祖母强迫亚述的诸侯向亚述巴尼拔宣誓效忠，但权力的更迭是和平的。一年后，沙马什-舒姆-乌金加冕，尽管他们的父亲希望他们仍然是“平等的兄弟”，但亚述巴尼拔有意将权力引向自己，要求他的兄弟宣誓效忠。这种对权力的攫取预示着他统治时期的事件。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_BOOM_ASHURBANIPAL_CHAPTER_HISTORY_PARA_3", "With his power consolidated in the Assyrian heartland, Ashurbanipal swiftly set about bringing the rest of the empire under his firm control. Two rebellions came with the death of Esarheddon, in Egypt and Elam. Ashurbanipal, who had been fighting political intrigue, had not opposed them, but once he had gathered his strength, he swiftly put down both rebellions, taking back the cities which had been lost to the rebels and sacking them as punishment. Following this, a series of additional rebellions popped up. Ashurbanipal crushed them with a ruthless efficiency for which he would become infamous, and even marched into the Elam homeland, which had supported the rebellion, and killed all their supporters."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_BOOM_ASHURBANIPAL_CHAPTER_HISTORY_PARA_3", "随着他在亚述中心地带的权力得到巩固，亚述巴尼拔迅速着手将帝国的其他地区置于他的牢固控制之下。随着阿萨哈东的死亡，埃及和埃兰发生了两起叛乱。一直在与政治阴谋作斗争的亚述巴尼拔一时并没有镇压他们，但一到他集结了力量的时候，就迅速平定了这两场叛乱，夺回了被叛乱者攻陷的城市，并洗劫了它们作为惩罚。在这之后，又出现了一系列的叛乱。亚述巴尼拔以无情的效率粉碎了这些叛乱，他因此而声名狼藉。甚至进军支持叛乱的埃兰，并杀死了叛军所有的支持者。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_BOOM_ASHURBANIPAL_CHAPTER_HISTORY_PARA_4", "At this point, Shamash-shum-ukin had been chafing extensively under Ashurbanipal's iron fist. Although he supposedly was king of all of Babylonia, in reality he only controlled Babylon and some of the surrounding territory. With growing dissatisfaction toward the balance of power and Ashurbanipal's poor treatment of him, Shamash-shum-ukin revolted in 652BC, seeking Babylonian independence under his own rule. His resistance was strengthened by the discontent of other conquered peoples in the Assyrian Empire, who supported his rebellion."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_BOOM_ASHURBANIPAL_CHAPTER_HISTORY_PARA_4", "此时，沙马什-舒姆-乌金已经，面对亚述巴尼拔的铁腕已经大伤脑筋了。虽然他据说是整个巴比伦的国王，但实际上他只控制了巴比伦和周边的一些领土。由于对权力平衡和亚述巴尼拔对他的恶劣待遇越来越不满，公元前652年，沙马什-舒姆-乌金起义，寻求巴比伦在自己的统治下独立。他的反抗因亚述帝国其他被征服民族的不满而得到加强，他们支持他的叛乱。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_BOOM_ASHURBANIPAL_CHAPTER_HISTORY_PARA_5", "Despite his many allies, Shamash-shum-ukin was unable to halt Ashurbanipal's advances. By 650BC, the Assyrian armies had reached the gates of Babylon itself, kicking off a siege that lasted two years. When the city finally fell, Ashurbanipal once again demonstrated his cruelty, killing thousands of citizens of the city, desecrating their corpses, pillaging their treasures, and starting a fire that ravaged the city. Shamash-shum-ukin is also believed to have died in this fire. Ashurbanipal appointed a vassal king in his place."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_BOOM_ASHURBANIPAL_CHAPTER_HISTORY_PARA_5", "尽管沙马什-舒姆-乌金拥有诸多盟友，但他依然无阻挡亚述巴尼拔的前进。在公元前650年时，亚述军队已经到达巴比伦城下，开始了持续两年的围城。当城市最终陷落时，亚述巴尼拔再次展示了他的残忍。他杀死了数千市民，亵渎了他们的尸体，掠夺了他们的宝藏，并防火焚烧了整座城市。沙马什-舒姆-乌金据说在火灾中丧生。亚述巴尼拔安插了一名傀儡国王取而代之。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_BOOM_ASHURBANIPAL_CHAPTER_HISTORY_PARA_6", "Following the defeat of his brother, Ashurbanipal embarked on several more campaigns throughout the Middle East and Asia. He began with the Elamites, who had supported Shamash-shum-ukin during the rebellion. The Elamite kings were weak and could not stand up to Ashurbanipal's threats, and when he invaded Elam he utterly crushed their civilization, desecrating their tombs, looting holy relics, and razed their cities to the ground. All the Elamite people he carried away as workmen or slaves and their former vassals he made his own. Following this victory, Ashurbanipal also made a series of incursions into Arabic lands, which although did not result in captured territory, did net him huge amounts of plunder."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_BOOM_ASHURBANIPAL_CHAPTER_HISTORY_PARA_6", "在击败他的兄弟后，阿舒尔巴尼帕又开始了在整个中东和亚洲的几次战役。他从埃兰人开始，埃兰人在叛乱期间曾支持过沙马什-舒姆-乌金。埃兰国王很软弱，无法抵御阿舒尔巴尼帕的威胁，当他入侵埃兰时，彻底粉碎了他们的文明，亵渎他们的坟墓，掠夺圣物，并将他们的城市夷为平地。所有的埃兰人都被他作为工人或奴隶带走了，他们以前的附庸也被他变成了自己的。在这次胜利之后，亚述巴尼拔还对阿拉伯人的土地进行了一系列的入侵，虽然没有夺取领土，但却使他获得了大量的财富。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_BOOM_ASHURBANIPAL_CHAPTER_HISTORY_PARA_7", "Although Ashurbanipal was characteristically cruel and brutal toward his enemies, he was well-loved by his people, and much of the loot he obtained from his campaigns was spent in public works projects or other works toward scientific or cultural advancement. He is known for his patronage of artists, and art produced under his rule is characteristically different from art from other rulers."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_BOOM_ASHURBANIPAL_CHAPTER_HISTORY_PARA_7", "尽管亚述巴尼拔的特点是对敌人残酷无情，但他很受亚述人民的爱戴，他从战役中获得的大部分战利品都被用于公共工程项目或其他科学或文化进步的工程。他以对艺术家的资助而闻名，在他统治下产生的艺术品与其他统治者的艺术品有着明显的不同。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_BOOM_ASHURBANIPAL_CHAPTER_HISTORY_PARA_8", "Ashurbanipal's crowning achievement was the Library of Ashurbanipal. Ashurbanipal believed himself strong in both body and mind, and as such, he created the first universal library, which became the largest library in the world at the time, and for long after, unsurpassed until the Library of Alexandria. The library was filled with texts both Assyrian in origin and many others taken from the conquered empires that Ashurbanipal had subjugated, as such, it was a momentous undertaking, and widely known in the ancient Mesopotamian world."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_BOOM_ASHURBANIPAL_CHAPTER_HISTORY_PARA_8", "亚述巴尼拔的最高成就是亚述巴尼拔图书馆。亚述巴尼拔认为自己的身体和心灵都很强大，因此，他创建了第一个跨文明的普世图书馆，这成为了当时世界上最大的图书馆，并持续了很长一段时间，直到亚历山大图书馆建成才被超越。该图书馆充满了源自亚述的书籍和许多其他来自亚述巴尼拔征服的帝国的书籍，因此，这是一项巨大的工程，在古代美索不达米亚世界广为人知。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_BOOM_ASHURBANIPAL_CHAPTER_HISTORY_PARA_9", "Despite Ashurbanipal's demonstrations of military prowess and advancements in Assyrian power and culture, he was unable to hold the empire together. The death of Shamash-shum-ukin kicked off massive unrest in the Assyrian empire, due to the death of a member of the Assyrian royal family and the damage done to a huge part of the Assyrian Empire. By the time of Ashurbanipal's death in 631BC, internal political strife and numerous rebellions had reduced the Assyrian Empire to a shadow of its former self, and with his death the empire crumbled completely."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_BOOM_ASHURBANIPAL_CHAPTER_HISTORY_PARA_9", "尽管亚述巴尼拔展示了军事才能，并在亚述人的军事和文化方面取得了进步，但他还是无法将帝国维持下去。由于亚述王室成员的死亡和亚述帝国很大一部分地区的荒芜，沙马什-舒姆-乌金的死亡拉开了亚述帝国大规模动荡的序幕。到公元前631年亚述巴尼拔去世时，内部的政治纷争和众多的叛乱已经使亚述帝国变成了它以前的影子，随着他的去世，帝国彻底崩溃了。"),
("en_US", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_BOOM_ASSYRIA_CHAPTER_HISTORY_PARA_1", "Assyria began as a city under the control of the empire of neo-Sumeria in the 21st century BC. It became an independent city-state briefly, but its status as a trade center and lack of military strength made it a target of conquest, and possession of the city changed several times over the next few centuries. Finally, in the 14th century BC, the Assyrians' latest ruler, the kingdom of Mitanni, collapsed, leaving them as an independent state once again under the rule of Ashur-uballit I."),
("zh_Hans_CN", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_BOOM_ASSYRIA_CHAPTER_HISTORY_PARA_1", "公元前21世纪，亚述开始成为新苏美尔帝国控制下的一个城市。它曾短暂地成为一个独立的城邦，但其作为贸易中心的地位和军事力量的缺乏使其成为被征服的目标，在接下来的几个世纪中，该城市的拥有权几经变化。最后，在公元前14世纪，亚述人的最新统治者米坦尼王国崩溃了，使他们再次成为亚述乌巴立特一世统治下的独立国家。"),
("en_US", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_BOOM_ASSYRIA_CHAPTER_HISTORY_PARA_2", "With the fall of Mitanni, many territories near Assyrian land became ripe for conquest. Taking advantage of this, many of the early Assyrian kings led campaigns into said territory. Thus, this period in Assyrian history, known as Middle Assyria, was marked by significant expansion and even defeats of other major empires. Notably, the Assyrians defeated the Hittites at the battle of Nihriya in 1237BC, and even briefly conquered sections of Babylonia."),
("zh_Hans_CN", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_BOOM_ASSYRIA_CHAPTER_HISTORY_PARA_2", "随着米坦尼的沦陷，亚述土地附近的许多领土成为合适的征服对象。利用这一点，许多早期亚述国王通过战争入侵上述领土。因此，亚述历史上的这一时期被称为中亚述，其特点是显著扩张，甚至打败了其他主要帝国。值得注意的是，亚述人在公元前1237年的尼赫里亚战役中打败了赫梯人，甚至还短暂地征服了巴比伦的部分地区。"),
("en_US", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_BOOM_ASSYRIA_CHAPTER_HISTORY_PARA_3", "However, following the assassination of Tukulti-Ninurta I, who had destablized Assyria by attemnpting to move the capital away from Assur, the empire's power fragmented, following kings were unable to hold on to Assyrian territory and the empire constantly grew or shrunk in cycles, as conquests were made by various powerful Assyrian kings, then immediately lost again. The Assyrian decline continued until the ascension of Ashur-dan II in 943BC. Under his rule, the Assyrian decline finally came to an end, and the Neo-Assyrian empire began."),
("zh_Hans_CN", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_BOOM_ASSYRIA_CHAPTER_HISTORY_PARA_3", "然而，在图库尔蒂尼努尔塔一世被暗杀后，由于他试图将首都迁离亚述，从而破坏了亚述的稳定，帝国的力量四分五裂，随后的国王无法守住亚述的领土，帝国不断地循环增长或式微，因为各个强大的亚述国王进行了征服，然后又立即失去。亚述的衰落一直持续到公元前943年亚述丹二世的登基。在他的统治下，亚述的衰落终于结束了，新亚述帝国也开始了。"),
("en_US", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_BOOM_ASSYRIA_CHAPTER_HISTORY_PARA_4", "With the beginning of the Neo-Assyrian empire, many Assyrian kings were able to make new forays into the land that they were previously unable to hold on to. Particularly important were the conquests of Adad-nirari II, who was not only able to conquer and keep lands far from the Assyrian heartland, but also able to gain the recognition of the Babylonian king at the time, Nabu-shuma-ukin I. The two kings signed a border treaty and were joined through marriage."),
("zh_Hans_CN", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_BOOM_ASSYRIA_CHAPTER_HISTORY_PARA_4", "随着新亚述帝国的开始，许多亚述国王能够向他们以前无法坚守的土地进行新的进军。特别重要的是阿达德尼拉里二世的征服，他不仅能够征服并保持远离亚述中心地带的土地，而且还能够获得当时的巴比伦国王那布舒玛乌金一世的承认。"),
("en_US", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_BOOM_ASSYRIA_CHAPTER_HISTORY_PARA_5", "The rise of Assyria continued under Ashurnasirpal II, who was both brutally cruel to those who rebelled against his rule, yet also surprisingly caring of his people, financing a number of building projects, creating water and food reserves, as well as temples, offices, gardens, and various other infrastructure using the plunder from his campaigns."),
("zh_Hans_CN", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_BOOM_ASSYRIA_CHAPTER_HISTORY_PARA_5", "亚述在亚述巴尼拔二世时期继续崛起，他对那些反抗他的统治的人很残酷，又出人意料地关心他的人民，资助了一些建筑项目，建立了水和粮食储备，以及利用他的战役中的掠夺物建造了寺庙、政府建筑、花园和各种其他基础设施。"),
("en_US", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_BOOM_ASSYRIA_CHAPTER_HISTORY_PARA_6", "Following this period however, the kings of Assyria lost power, and the nobles and magnates of the Assyrian empire wielded much more infleunce. Assyria suffered a number of minor defeats during this period, and was weakened enough to be unable to expand as successfully as it had been able to previously."),
("zh_Hans_CN", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_BOOM_ASSYRIA_CHAPTER_HISTORY_PARA_6", "然而，在此之后，亚述的国王们失去了权力，亚述帝国的贵族和富商们掌握了更多的权力。亚述在这一时期遭受了一些小的失败，并被削弱到无法像以前那样成功扩张。"),
("en_US", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_BOOM_ASSYRIA_CHAPTER_HISTORY_PARA_7", "The ascension and rule of Tiglath-Pileser III marked the end of the power of magnates and the beginning of Assyria's imperial period. While prior kings focused upon conquest, with little regard to the ruling and beauracracy aspects of running an empire, Tiglath-Pileser III made huge advances in this regard, weakening the magnates, as well as establishing royal governors in newly organized provinces and resettling conquered peoples in order to prevent rebellion. In addition, he also conquered Babylonia, creating the system of two kingships assumed by the ruler of Assyria."),
("zh_Hans_CN", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_BOOM_ASSYRIA_CHAPTER_HISTORY_PARA_7", "提格拉特帕拉沙尔三世的登基和统治标志着寡头权力的结束和亚述帝国时期的开始。之前的国王专注于征服，很少考虑管理帝国的统治和管理方面的问题，而提格拉特帕拉沙尔三世在这方面取得了巨大的进步，削弱了富商们的力量，并在新组织的省份设立了皇家总督，重新安置了被征服的人民，以防止叛乱。此外，他还征服了巴比伦，建立了由亚述统治者担任的两个王位的制度。"),
("en_US", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_BOOM_ASSYRIA_CHAPTER_HISTORY_PARA_8", "Following the death of Tiglath-Pileser, his son Shalmaneser ascended to the throne, but was deposed by Sargon II, who took the throne by force, causing considerable political unrest without Assyria. Due to his fear of retribution from his enemies, Sargon II constructed an entirely new capital, called Dur-Sharrukin, notable for the fact that it was built from the ground up and not an existing city."),
("zh_Hans_CN", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_BOOM_ASSYRIA_CHAPTER_HISTORY_PARA_8", "提格拉特帕拉沙尔死后，他的儿子沙尔马那塞尔登上了王位，但被萨尔贡二世废黜，他用武力夺取了王位，在亚述国内引起了相当大的政治动荡。由于害怕敌人的报复，萨尔贡二世建造了一个全新的首都，名为杜尔-沙鲁金，值得注意的是，它是从头开始建造的，而不是现有的城市。"),
("en_US", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_BOOM_ASSYRIA_CHAPTER_HISTORY_PARA_9", "After Sargon II's death in battle, his son Sennacherib reigned, and his reign was relatively uneventful, til the time came for the succession, when his eldest son, Arda-Mulissu, killed him over an argument over the succession. Thus, a younger son of Sennacherib, Esarhaddon, took Ninevah, and was able to force out Arda-Mulissu and take the throne."),
("zh_Hans_CN", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_BOOM_ASSYRIA_CHAPTER_HISTORY_PARA_9", "萨尔贡二世战死后，他的儿子辛那赫里布在位，他的统治相对平稳，直到继位的时候，他的长子阿尔达穆利苏因为继承权的争执而将他杀死。因此，辛那赫里布的一个小儿子阿萨哈东占领了尼尼微，并能够逼出阿尔达穆利苏并夺取王位。"),
("en_US", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_BOOM_ASSYRIA_CHAPTER_HISTORY_PARA_10", "Although Esarhaddon and his son Ashurbanipal made enormous leaps in governing and conquest, including the capture of Egypt and the building of the Library of Ashurbanipal, the empire had become too large at this point to effectively govern, and various rebellions and internal unrest led to its fall in 622BC, when Ashurbanipal's young and inexperienced sons lost the Assyrian capital of Ninevah, marking the end of the Assyrian empire."),
("zh_Hans_CN", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_BOOM_ASSYRIA_CHAPTER_HISTORY_PARA_10", "尽管阿萨哈东和他的儿子亚述巴尼拔在治理和征服方面取得了巨大的飞跃，包括攻占埃及和建造亚述巴尼拔图书馆，但此时的帝国已经变得过于庞大，无法有效治理，各种叛乱和内乱导致了公元前622年的衰落，亚述巴尼拔年轻而缺乏经验的儿子们失去了亚述的首都尼尼微，标志着亚述帝国的结束。"),
("en_US", "LOC_PEDIA_UNITS_PAGE_UNIT_BOOM_SIEGE_ENGINE_CHAPTER_HISTORY_PARA_1", "The oldest known siege towers date to their use by the armies of the neo-Assyrian Empire c. 9th century BC. Bas-reliefs from the reign of Ashurbanipal II depict siege towers at the walls of enemy towns. At the time, mud-brick walls were generally sufficient protection against the ancient armies of Mesopotamia, but siege towers used by the Assyrians allowed them to overwhelm enemy towns quickly and efficiently, providing their empire with a means to grow virtually unchecked for three centuries."),
("zh_Hans_CN", "LOC_PEDIA_UNITS_PAGE_UNIT_BOOM_SIEGE_ENGINE_CHAPTER_HISTORY_PARA_1", "已知最古老的攻城塔可以追溯到公元前9世纪新亚述帝国的军队使用。亚述巴尼拔二世统治时期的浮雕描绘了敌方城镇墙壁上的攻城塔。当时，泥砖墙通常足以保护美索不达米亚的古代军队，但亚述人使用的攻城塔使他们能够快速有效地压倒敌人的城镇，为他们的帝国提供了三个世纪以来几乎不受限制的发展手段。"),
("en_US", "LOC_PEDIA_IMPROVEMENTS_PAGE_IMPROVEMENT_BOOM_LAMASSU_CHAPTER_HISTORY_PARA_1", "The Lamassu originated as a form of worship to the goddess Lama, who was a protective goddess worshipped by the Sumerians. The Assyrians adapted this deity, renaming her to Lamma, and gave her half human, half animal features. Due to the protective power that the goddess was thought to have, sculptures of half human, half winged lions or bulls were placed at the entrances to palaces or other important areas, in order to safeguard what was within"),
("zh_Hans_CN", "LOC_PEDIA_IMPROVEMENTS_PAGE_IMPROVEMENT_BOOM_LAMASSU_CHAPTER_HISTORY_PARA_1", "拉玛苏起源于对拉玛女神的一种崇拜，拉玛女神是苏美尔人崇拜的保护神。亚述人对这一神灵进行了改造，将其改名为兰玛，并赋予她半人半兽的特征。由于该女神被认为具有保护能力，半人半翼的狮子或公牛的雕塑被放置在宫殿或其他重要区域的入口处，以保护里面的东西。"),
("en_US", "LOC_PEDIA_BUILDINGS_PAGE_BUILDING_BOOM_ROYAL_LIBRARY_CHAPTER_HISTORY_PARA_1", "The Library of Ashurbanipal was the greatest, most comprehensive library in the ancient world, unsurpassed until the Library of Alexandria, 400 years later. Despite Ashurbanipal's fame as commander and brutal conquerer, he was also an intellectual, and as he conquered he also constantly collected various texts from both conquered and his own lands, which he gathered into his library. Some of the most well-known ancient texts today, such as the Epic of Gilgamesh, were found in the library."),
("zh_Hans_CN", "LOC_PEDIA_BUILDINGS_PAGE_BUILDING_BOOM_ROYAL_LIBRARY_CHAPTER_HISTORY_PARA_1", "亚述巴尼拔的图书馆是古代世界最伟大、最全面的图书馆，直到400年后的亚历山大图书馆才被超越。尽管亚述巴尼拔作为指挥官和残酷的征服者而闻名，但他也是一位知识分子，在他征服的同时，他也不断地从被征服者和自己的土地上收集各种文本，并将其收集到他的图书馆。今天一些最著名的古代文献，如《吉尔伽美什史诗》，都是在图书馆里发现的。"),
