-- Loading Text
("en_US", "LOC_LOADING_INFO_LEADER_BOOM_ASHURBANIPAL", "Ashurbanipi the Great, you rule Assyria under the will of Asur as the sole monarch of the Fertile Crecent and the entire world. Your show love to your people and cruelty to your foes, filling your library with works that sing your praise. Relieve yourself of all doubts and lead Assyria into luminosity promised by Asur!"),
("zh_Hans_CN", "LOC_LOADING_INFO_LEADER_BOOM_ASHURBANIPAL", "伟大的亚述巴尼拔，您是以阿苏尔旨意去统治亚述、新月沃地乃至全世界的唯一的王。对敌人，您很残暴，对人民，您却很仁慈，这使您的图书馆中有着浩如烟海的文献，纪录您的丰功伟绩。抛下疑虑，带领亚述走进阿苏尔的光芒之中吧。");

-- Nebuchadnezzar
insert or replace into LocalizedText (Language, Tag, Text) values
("en_US", "LOC_DIPLO_ACCEPT_DECLARE_FRIEND_FROM_HUMAN_LEADER_NEBUCHADNEZZAR_II_ANY", "Bravo, the wonders of our two countries mirroring each other!"),
("zh_Hans_CN", "LOC_DIPLO_ACCEPT_DECLARE_FRIEND_FROM_HUMAN_LEADER_NEBUCHADNEZZAR_II_ANY", "好啊，我们两国的奇观相映生辉！"),
("en_US", "LOC_DIPLO_ACCEPT_DELEGATION_FROM_HUMAN_LEADER_NEBUCHADNEZZAR_II_ANY", "Your envoys are visiting my wonders, while I am inspecting your gifts"),
("zh_Hans_CN", "LOC_DIPLO_ACCEPT_DELEGATION_FROM_HUMAN_LEADER_NEBUCHADNEZZAR_II_ANY", "您的使者在游览我的奇观，而我正在检视您的赠礼。"),
("en_US", "LOC_DIPLO_ACCEPT_MAKE_DEAL_FROM_AI_LEADER_NEBUCHADNEZZAR_II_ANY", "Maduk agrees, and so does Babylon."),
("zh_Hans_CN", "LOC_DIPLO_ACCEPT_MAKE_DEAL_FROM_AI_LEADER_NEBUCHADNEZZAR_II_ANY", "马杜克同意，巴比伦也同意。"),
("en_US", "LOC_DIPLO_ACCEPT_OPEN_BORDERS_FROM_HUMAN_LEADER_NEBUCHADNEZZAR_II_ANY", "My people will pass through peacefully."),
("zh_Hans_CN", "LOC_DIPLO_ACCEPT_OPEN_BORDERS_FROM_HUMAN_LEADER_NEBUCHADNEZZAR_II_ANY", "我的人马会和平的通行。"),
("en_US", "LOC_DIPLO_DECLARE_WAR_FROM_AI_LEADER_NEBUCHADNEZZAR_II_ANY", "Soon, your people will build me greater wonders."),
("zh_Hans_CN", "LOC_DIPLO_DECLARE_WAR_FROM_AI_LEADER_NEBUCHADNEZZAR_II_ANY", "很快，你的人民将为我建造更雄伟的奇观。"),
("en_US", "LOC_DIPLO_DECLARE_WAR_FROM_HUMAN_LEADER_NEBUCHADNEZZAR_II_ANY", "Soon, your people will build me greater wonders."),
("zh_Hans_CN", "LOC_DIPLO_DECLARE_WAR_FROM_HUMAN_LEADER_NEBUCHADNEZZAR_II_ANY", "很快，你的人民将为我建造更雄伟的奇观。"),
("en_US", "LOC_DIPLO_DEFEAT_FROM_AI_LEADER_NEBUCHADNEZZAR_II_ANY", "Babylon has fallen! Some deem me insane. My vain attempts to rule with violence have failed. Maybe the Fertile Crecent awaits a merciful monarch."),
("zh_Hans_CN", "LOC_DIPLO_DEFEAT_FROM_AI_LEADER_NEBUCHADNEZZAR_II_ANY", "巴比伦陨落了！有人认为我已经疯癫，我没有……我用暴力探索统治方式的道途已经穷尽，可能新月沃地需要一个仁君……"),
("en_US", "LOC_DIPLO_DEFEAT_FROM_HUMAN_LEADER_NEBUCHADNEZZAR_II_ANY", "Babylon has fallen! Some deem me insane. My vain attempts to rule with violence have failed. Maybe the Fertile Crecent awaits a merciful monarch."),
("zh_Hans_CN", "LOC_DIPLO_DEFEAT_FROM_HUMAN_LEADER_NEBUCHADNEZZAR_II_ANY", "巴比伦陨落了！有人认为我已经疯癫，我没有……我用暴力探索统治方式的道途已经穷尽，可能新月沃地需要一个仁君……"),
("en_US", "LOC_DIPLO_DELEGATION_FROM_AI_LEADER_NEBUCHADNEZZAR_II_ANY", "Babylon has brought you treats of the Fertile Crecent."),
("zh_Hans_CN", "LOC_DIPLO_DELEGATION_FROM_AI_LEADER_NEBUCHADNEZZAR_II_ANY", "巴比伦给您送来许多美食，它们能让你体会到新月沃土的富饶。"),
("en_US", "LOC_DIPLO_DENOUNCE_FROM_AI_LEADER_NEBUCHADNEZZAR_II_ANY", "My sword will show you your cowardice."),
("zh_Hans_CN", "LOC_DIPLO_DENOUNCE_FROM_AI_LEADER_NEBUCHADNEZZAR_II_ANY", "我将用自己的刀剑让你看看你是多么外强中干。（谴责你）"),
("en_US", "LOC_DIPLO_DENOUNCE_FROM_HUMAN_LEADER_NEBUCHADNEZZAR_II_ANY", "Do you need my army to teach you how to be a proper ruler?"),
("zh_Hans_CN", "LOC_DIPLO_DENOUNCE_FROM_HUMAN_LEADER_NEBUCHADNEZZAR_II_ANY", "你那样像一个统治者吗？要不要我用军队来教教你？"),
("en_US", "LOC_DIPLO_FIRST_MEET_LEADER_NEBUCHADNEZZAR_II_ANY", "Ah, it's pleasant to meet new faces. I am the Nebuchadnezzar, the king of Babylon, Sumeria and Akkad, the ruler of the world."),
("zh_Hans_CN", "LOC_DIPLO_FIRST_MEET_LEADER_NEBUCHADNEZZAR_II_ANY", "啊，见到新面孔的感觉真不错。我是迦勒底王尼布甲尼撒，巴比伦之王，苏美尔和阿卡德之王，世界之主。"),
("en_US", "LOC_DIPLO_FIRST_MEET_NEAR_INITIATOR_POSITIVE_LEADER_NEBUCHADNEZZAR_II_ANY", "My astrologists have predicted that you will accept my generous offer."),
("zh_Hans_CN", "LOC_DIPLO_FIRST_MEET_NEAR_INITIATOR_POSITIVE_LEADER_NEBUCHADNEZZAR_II_ANY", "我的占星术士预见了你会同意我的请求。"),
("en_US", "LOC_DIPLO_FIRST_MEET_NO_MANS_INFO_EXCHANGE_LEADER_NEBUCHADNEZZAR_II_ANY", "Should you be willing to visit my capital, you would be blessed with the view of the rarest wonders and gardens."),
("zh_Hans_CN", "LOC_DIPLO_FIRST_MEET_NO_MANS_INFO_EXCHANGE_LEADER_NEBUCHADNEZZAR_II_ANY", "如果你来我们的首都，你就能看到世所罕见的奇观与花园。"),
("en_US", "LOC_DIPLO_FIRST_MEET_VISIT_RECIPIENT_LEADER_NEBUCHADNEZZAR_II_ANY", "You would die in remorse if you miss out on the view of my heavenly gardens."),
("zh_Hans_CN", "LOC_DIPLO_FIRST_MEET_VISIT_RECIPIENT_LEADER_NEBUCHADNEZZAR_II_ANY", "我的花园如同天堂一般，不看一眼就有可能后悔一生。"),
("en_US", "LOC_DIPLO_GREETING_LEADER_NEBUCHADNEZZAR_II_ANY", "Maduk shields us, and I'm sure that your archon does as well."),
("zh_Hans_CN", "LOC_DIPLO_GREETING_LEADER_NEBUCHADNEZZAR_II_ANY", "马杜克保护着我们，我想你的守护神也在保护你。"),
("en_US", "LOC_DIPLO_KUDO_EXIT_LEADER_NEBUCHADNEZZAR_II_ANY", "Your military suffices to protect your prosperity. This is good!. I hope that we could learn peacefully from each other."),
("zh_Hans_CN", "LOC_DIPLO_KUDO_EXIT_LEADER_NEBUCHADNEZZAR_II_ANY", "你的军队有能力保护你的发展成果，这很好！我希望我们可以和平的互相学习，共同发展。"),
("en_US", "LOC_DIPLO_KUDO_LEADER_NEBUCHADNEZZAR_II_REASON_ANY", "(You are advanced in military and science)"),
("zh_Hans_CN", "LOC_DIPLO_KUDO_LEADER_NEBUCHADNEZZAR_II_REASON_ANY", "（你的科技和军事都很发达）"),
("en_US", "LOC_DIPLO_MAKE_ALLIANCE_FROM_AI_LEADER_NEBUCHADNEZZAR_II_ANY", "The most acclaimed astroogists around believes in the bright prospect of our alliance."),
("zh_Hans_CN", "LOC_DIPLO_MAKE_ALLIANCE_FROM_AI_LEADER_NEBUCHADNEZZAR_II_ANY", "巴比伦的世界上最好的占星师都认为这个同盟将会有光辉的未来"),
("en_US", "LOC_DIPLO_MAKE_PEACE_AI_ACCEPT_DEAL_LEADER_NEBUCHADNEZZAR_II_ANY", "Ongoing warfare can only undermine my rule. Should we make peace?"),
("zh_Hans_CN", "LOC_DIPLO_MAKE_PEACE_AI_ACCEPT_DEAL_LEADER_NEBUCHADNEZZAR_II_ANY", "再继续战争只会动摇你我的统治，不如就此休战？"),
("en_US", "LOC_DIPLO_MAKE_PEACE_AI_ACCEPT_DEAL_LEADER_NEBUCHADNEZZAR_II_ANY", "No! I will not relent untill you are taken captive."),
("zh_Hans_CN", "LOC_DIPLO_MAKE_PEACE_AI_ACCEPT_DEAL_LEADER_NEBUCHADNEZZAR_II_ANY", "不，我将继续战斗，直到你变成我的俘虏！"),
("en_US", "LOC_DIPLO_MAKE_PEACE_FROM_AI_LEADER_NEBUCHADNEZZAR_II_ANY", "This war has lost all meanings. Broken families wail in pain."),
("zh_Hans_CN", "LOC_DIPLO_MAKE_PEACE_FROM_AI_LEADER_NEBUCHADNEZZAR_II_ANY", "这场战争已经失去了意义，不要再无意义的制造孤儿寡母了。"),
("en_US", "LOC_DIPLO_OPEN_BORDERS_FROM_AI_LEADER_NEBUCHADNEZZAR_II_ANY", "If you open your borders to Babylon, you are sure to profit from the riches of the Fertile Crecent."),
("zh_Hans_CN", "LOC_DIPLO_OPEN_BORDERS_FROM_AI_LEADER_NEBUCHADNEZZAR_II_ANY", "如果你跟巴比伦互相开放边境，就能从新月沃地的财富中获取可观的利润。"),
("en_US", "LOC_DIPLO_OPEN_BORDERS_FROM_AI_LEADER_NEBUCHADNEZZAR_II_ANY", "If you open your borders to Babylon, you are sure to profit from the riches of the Fertile Crecent."),
("zh_Hans_CN", "LOC_DIPLO_OPEN_BORDERS_FROM_AI_LEADER_NEBUCHADNEZZAR_II_ANY", "如果你跟巴比伦互相开放边境，就能从新月沃地的财富中获取可观的利润。"),
("en_US", "LOC_DIPLO_REJECT_DECLARE_FRIEND_FROM_HUMAN_LEADER_NEBUCHADNEZZAR_II_ANY", "Don't even think about it. You are no match with Babylon."),
("zh_Hans_CN", "LOC_DIPLO_REJECT_DECLARE_FRIEND_FROM_HUMAN_LEADER_NEBUCHADNEZZAR_II_ANY", "别做梦，你还配不上跟巴比伦相比。"),
("en_US", "LOC_DIPLO_REJECT_DELEGATION_FROM_HUMAN_LEADER_NEBUCHADNEZZAR_II_ANY", "Look at your so called 'gifts'. They bring shame to my treasury."),
("zh_Hans_CN", "LOC_DIPLO_REJECT_DELEGATION_FROM_HUMAN_LEADER_NEBUCHADNEZZAR_II_ANY", "你瞧瞧你那些玩意，放在巴比伦只能让我的国库蒙尘。"),
("en_US", "LOC_DIPLO_REJECT_MAKE_DEAL_FROM_AI_LEADER_NEBUCHADNEZZAR_II_ANY", "Nonsense!"),
("zh_Hans_CN", "LOC_DIPLO_REJECT_MAKE_DEAL_FROM_AI_LEADER_NEBUCHADNEZZAR_II_ANY", "动动脑子，别做傻事。"),
("en_US", "LOC_DIPLO_REJECT_OPEN_BORDERS_FROM_HUMAN_LEADER_NEBUCHADNEZZAR_II_ANY", "I see your vulgar soldiers interupting the peaceful llves of my people."),
("zh_Hans_CN", "LOC_DIPLO_REJECT_OPEN_BORDERS_FROM_HUMAN_LEADER_NEBUCHADNEZZAR_II_ANY", "我看你那些粗鲁的士兵只会打扰迦勒底人的生活。"),
("en_US", "LOC_DIPLO_WARNING_EXIT_LEADER_NEBUCHADNEZZAR_II_ANY", "Your holy sites are to be burnt, and your people are to be unslaved. Even if I'm not around to do it, some other leaders will do so for me."),
("zh_Hans_CN", "LOC_DIPLO_WARNING_EXIT_LEADER_NEBUCHADNEZZAR_II_ANY", "你如此羸弱，你的圣殿必然会被焚毁，你的人民必然会被奴役。即时我不这样做，也会有其他领袖这样做的。"),
("en_US", "LOC_DIPLO_WARNING_LEADER_NEBUCHADNEZZAR_II_REASON_ANY", "(You have constructed wonders but are unable to protect them。）"),
("zh_Hans_CN", "LOC_DIPLO_WARNING_LEADER_NEBUCHADNEZZAR_II_REASON_ANY", "（你建造了很多奇观却无力保护它们）"),
("en_US", "LOC_DIPLO_WARNING_TOO_MANY_TROOPS_NEAR_ME_LEADER_NEBUCHADNEZZAR_II_ANY", "If your soldiers are simply wandering about oustide Babylon, I'm fine with it. However, if they dare step inside, they are doomed."),
("zh_Hans_CN", "LOC_DIPLO_WARNING_TOO_MANY_TROOPS_NEAR_ME_LEADER_NEBUCHADNEZZAR_II_ANY", "如果你的军队只是在巴比伦边境外走走，那我无所谓，但是如果他们敢跨入巴比伦一步，他们就将毁灭。"),
("en_US", "LOC_LEADER_NEBUCHADNEZZAR_II_NAME", "Nebuchadnezzar II"),
("zh_Hans_CN", "LOC_LEADER_NEBUCHADNEZZAR_II_NAME", "尼布甲尼撒二世"),
("en_US", "LOC_AGENDA_BABYLONIAN_CAPTIVITY_NAME", "Babylonian Captivity"),
("zh_Hans_CN", "LOC_AGENDA_BABYLONIAN_CAPTIVITY_NAME", "巴比伦之囚"),
("en_US", "LOC_LOADING_INFO_LEADER_NEBUCHADNEZZAR_II", "Nebuchadnezzar, Maduk watches you as you rule the Furtile Crecent. You created the magnificent city of Babylon. Your spectacles scrape the skies; your force enslave your foes. Use all you have to achieve enterprise beyond the imagination of astrologists."),
("zh_Hans_CN", "LOC_LOADING_INFO_LEADER_NEBUCHADNEZZAR_II", "尼布甲尼撒，马尔杜克注视着您一步步统一新月沃地。您修建了宏伟的巴比伦城，您的奇观高耸入天际。您的武力使奴隶臣服，外邦忌惮。用您所拥有的的一切去实现迦勒底最好的占星术士都难以想象的宏图伟业吧。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_NEBUCHADNEZZAR_II_CHAPTER_CAPSULE_BODY", "Nebuchadnezzar II is a strong domination leader and loves wonders. This makes him well-versed in all victories."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_NEBUCHADNEZZAR_II_CHAPTER_CAPSULE_BODY", "尼布甲尼撒二世是一位强有力的征服者而且爱好建造各种宏伟的奇观，这使得他有能力追求所有种类的胜利。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_NEBUCHADNEZZAR_II_CHAPTER_DETAILED_BODY", "When you play as Nebuchadnezzar II, you can conquer neaby cities and use them as your base to collect wonders."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_NEBUCHADNEZZAR_II_CHAPTER_DETAILED_BODY", "以尼布甲尼撒二世为领袖游玩巴比伦时，可以先准备军事以征服周边城市，然后以此为依托建造奇观，获取各种加成。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_NEBUCHADNEZZAR_II_CHAPTER_HISTORY_PARA_1", "In the late 7th century B.C., the once-dominant Neo-Assyrian Empire was declining. To its northwest lied the rich Anatolian kingdom of Lydia; to its east was the emerging Aryian power Medes; to the southwest, under the rule of Pharoh Psamtik I, Egypt was at war with Assyria to gain control over Canaan。 Under Assyrian rule, the Mesopotamia area was mainly populated by imigrated Semites and Chaldeans. In 626 B.C., the Babylonian governer of Assyria, Nabopolassar ceded from Assyria and launched a rebellion with Medes against Assyria, destroying it. Thus, Assyria ceased to exist as an independent political entity. The ageing Nabopolassar passed the leadership of the military to his young and competent son, Nebuchadnezzar. After he died, Nebuchadnezzar was crowned the new king of Neo-Babylon."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_NEBUCHADNEZZAR_II_CHAPTER_HISTORY_PARA_1", "公元前七世纪后半叶，称霸西亚一时的新亚述帝国已经走向衰落，在其西北是安纳托利亚富裕的吕底亚王国东部是新兴的雅利安人国家米底，在西南方埃及的第二十六王朝的普萨美提克一世也与亚述作战，希望摆脱亚述并且获得迦南。此时在亚述治下的两河流域，主体民族是迁入的闪米特语民族迦勒底人。他们也很反感亚述的暴政。公元前626年，亚述的巴比伦尼亚总督，迦勒底人那波帕拉萨尔宣布脱离亚述，起兵联合米底攻击亚述，最终摧毁了新亚述帝国。从此亚述在历史上不再以独立政治集体存在。而起兵后那波帕拉萨尔逐渐不能领兵，军队领导权主要由他年轻有为的儿子尼布甲尼撒继承。他病逝后，尼布甲尼撒成为巴比伦王，是为新巴比伦王尼布甲尼撒二世。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_NEBUCHADNEZZAR_II_CHAPTER_HISTORY_PARA_2", "The reign of Nebuchadnezzar is the final cimax of Babylon. He defreated Assyria, conquered Levant and Palestine, and drove the Egyptians out of Asia. He burnt to ashes the Beit HaMikdash, the holy site of Jeudism, and enslaved the Jews, after several attemptedrebellions by the Jews against Babylon. Although he is known as a militaristic leader, his diplomacy does not always involve force. Under his reign, Babylon was rebuilt as a great city, Although it might be Greek mythology that he built the Hanging Gardens for his wife, he did indeed built walls around the city of Babylon and on the border with Medes. However, similar to all empires rising and falling in the region, Neo-Babylon suffered through division and internal termoil. His sucessors was soon replaced by a genius militarist and merciful sovereign, Cyrus, opening a new chapter in the politics of West Asia."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_NEBUCHADNEZZAR_II_CHAPTER_HISTORY_PARA_2", "尼布甲尼撒二世的任期是巴比伦最后一个巅峰时期。他击败了亚述，征服了黎凡特和巴勒斯坦，将埃及人赶出了亚洲。对于对巴比伦一再被判的犹太人，他忍无可忍的焚毁了犹太人的所罗门圣殿，将犹太人掠夺到巴比伦为奴。虽然他一军事著称，但是他在外交方面其实并非一味使用武力，他结交吕底亚，与米底和亲。在他任期内，巴比伦被重新建立成一座伟大的城市，虽然他为他的米底王妃建了一座空中花园很可能是希腊人的传说。他的修建了巴比伦宏伟的城墙，还在巴比伦和米底边境修建了长城。然而，西亚上千年来的历史中充斥着在战争中崛起又在战争中陨落的帝国，新巴比伦也是如此。在他死后，新巴比伦经历了数个国王分立的内乱，很快被东方的一位有着天才的军事和仁慈的美德的君主——居鲁士取代，西亚的政治也迎来了新时代。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_NEBUCHADNEZZAR_II_QUOTE", "What can be better remembered? Towering wonders or brilliant mercy?"),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_NEBUCHADNEZZAR_II_QUOTE", "什么才能让后人铭记？高耸入云的巨塔还是光芒万丈的仁慈？"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_NEBUCHADNEZZAR_II_TITLE", "The king of Babylon, Sumeria and Akkad, the ruler of the universe."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_NEBUCHADNEZZAR_II_TITLE", "巴比伦之王，苏美尔与阿卡德之王，宇宙之王"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_NEBUCHADNEZZAR_II_DESCRIPTION", "Whenever a city is conquered, +5%[ICON_PRODUCTION] Production towards wonders (maximum +30%). Every occupied city provides +1[ICON_FOOD] Food and +1[ICON_PODUCTION] Production to cities founded by Babylon. Yields an extra 50 [ICON_GOLD] Gold from pilliaging and coastal raiding. When conquering a city, gains 30 [ICON_GOLD] Gold per population."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_NEBUCHADNEZZAR_II_DESCRIPTION", "每占领一座城市，建造奇观时+5% [ICON_Production] 生产力，最多+30%生产力。每个占领的城市为每个巴比伦建立的城市+1粮1锤。有掠夺单元格+50金，攻陷城市时，从城市每个人口额外获得30金。"),
("en_US", "LOC_TRAIT_HANGING_GARDENS_NAME", "The Hanging Gardens"),
("zh_Hans_CN", "LOC_TRAIT_HANGING_GARDENS_NAME", "空中花园"),
("en_US", "PEDIA_LEADERS_PAGE_LEADER_NEBUCHADNEZZAR_II_SUBTITLE", "The King of Neo-Babylon"),
("zh_Hans_CN", "PEDIA_LEADERS_PAGE_LEADER_NEBUCHADNEZZAR_II_SUBTITLE", "新巴比伦国王"),
("en_US", "LOC_DIPLO_MODIFIER_BABYLONIAN_CAPTIVITY_POSITIVE", "Nebuchadnezzar thinks that he could learn much from your military and scolars"),
("zh_Hans_CN", "LOC_DIPLO_MODIFIER_BABYLONIAN_CAPTIVITY_POSITIVE", "尼布甲尼撒觉得可以从你的军队和学者中学到许多"),
("en_US", "LOC_DIPLO_MODIFIER_BABYLONIAN_CAPTIVITY_NEGATIVE", "Nebuchadnezzar wants to enslave your people"),
("zh_Hans_CN", "LOC_DIPLO_MODIFIER_BABYLONIAN_CAPTIVITY_NEGATIVE", "尼布甲尼撒想把你的人民掠夺为奴");

-- Bulgaria
insert or replace into LocalizedText (Language, Tag, Text) values
("en_US", "LOC_CIVINFO_MER_BULGARIA_LOCATION", "Bulgaria"),
("zh_Hans_CN", "LOC_CIVINFO_MER_BULGARIA_LOCATION", "保加利亚"),
("en_US", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_MER_BULGARIA_CHAPTER_HISTORY_PARA_1", "The earliest evidence of hominid occupation discovered on what is today Bulgaria date from at least 1.4 million years ago. Around 5000 BC, a sophisticated civilization already existed and produced some of the first pottery and jewelry in the world. After 3000 BC, the Thracians appeared on the Balkan peninsula. In the late 6th century BC, most of what is nowadays Bulgaria came under the Persian Empire.[2] In the 470s BC, the Thracians formed the powerful Odrysian Kingdom, probably after the Persian defeat in Greece, which subsequently declined and Thracian tribes fell under Macedonian, Celtic and Roman domination. This mixture of ancient peoples was assimilated by the Slavs, who permanently settled on the peninsula after 500 AD."),
("zh_Hans_CN", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_MER_BULGARIA_CHAPTER_HISTORY_PARA_1", "在今天的保加利亚发现的最早的人类占领证据至少是在140万年前。公元前5000年左右，一个成熟的文明已经存在，并产生了一些世界上最早的陶器和珠宝。公元前3000年后，色雷斯人出现在巴尔干半岛上。公元前6世纪末，现今保加利亚的大部分地区归属波斯帝国。公元前470年代，色雷斯人形成了强大的奥德里亚王国，可能是在波斯人在希腊战败后，该王国随后衰落，色雷斯部落落入马其顿、凯尔特和罗马的统治之下。这种古代民族的混合体被斯拉夫人所同化，他们在公元500年后永久地定居在半岛上。"),
("en_US", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_MER_BULGARIA_CHAPTER_HISTORY_PARA_2", "Meanwhile, in 632 the Bulgars formed an independent state north of the Black sea that became known as Great Bulgaria under the leadership of Kubrat. Pressure from the Khazars led to the disintegration of Great Bulgaria in the second half of the 7th century. One of the Kubrat's successors, Asparukh, migrated with some of the Bulgar tribes to the area around the Danube delta, and subsequently conquered Scythia Minor and Moesia Inferior from the Byzantine Empire, expanding his new kingdom further into the Balkan Peninsula. A peace treaty with Byzantium in 681 and the establishment of a permanent Bulgarian capital at Pliska south of the Danube mark the beginning of the First Bulgarian Empire. The new state brought together Thracian remnants and Slavs under Bulgar rule, and a slow process of mutual assimilation began. In the following centuries Bulgaria established itself as a powerful empire, dominating the Balkans through its aggressive military traditions, which led to development of distinct ethnic identity.[5] Its ethnically and culturally diverse people united under a common religion, language and alphabet which formed and preserved the Bulgarian national consciousness despite foreign invasions and influences."),
("zh_Hans_CN", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_MER_BULGARIA_CHAPTER_HISTORY_PARA_2", "同时，在632年，保加尔人人在黑海以北形成了一个独立的国家，在库布拉特的领导下被称为大保加利亚。来自可萨人的压力导致了大保加利亚在7世纪下半叶的瓦解。库布拉特的继承人之一阿斯帕鲁克与一些保加利亚部落一起迁移到多瑙河三角洲周围地区，随后从拜占庭帝国手中征服了小斯基泰亚和下莫西亚，将他的新王国进一步扩展到巴尔干半岛。681年与拜占庭签订和平条约，并在多瑙河以南的普利斯卡建立了保加利亚的永久首都，标志着第一保加利亚帝国的开始。这个新的国家将色雷斯人的残余和斯拉夫人聚集在保加尔人的统治之下，并开始了一个缓慢的相互同化过程。在接下来的几个世纪里，保加利亚建立了自己强大的帝国，通过其侵略性的军事传统主宰了巴尔干地区，这导致了独特的民族身份的发展。其民族和文化上的多样的人民在共同的宗教、语言和字母下团结起来，形成并保存了保加利亚的民族意识，尽管受到外国的入侵和影响。"),
("en_US", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_MER_BULGARIA_CHAPTER_HISTORY_PARA_3", "In the 11th century, the First Bulgarian Empire collapsed under Rus' and Byzantine attacks, and became part of the Byzantine Empire until 1185. Then, a major uprising led by two brothers - Asen and Peter of the Asen dynasty, restored the Bulgarian state to form the Second Bulgarian Empire. After reaching its apogee in the 1230s, Bulgaria started to decline due to a number of factors, most notably its geographic position which rendered it vulnerable to simultaneous attacks and invasions from many sides. A peasant rebellion, one of the few successful such in history, established the swineherd Ivaylo as a Tsar. His short reign was essential in recovering - at least partially - the integrity of the Bulgarian state. A relatively thriving period followed after 1300, but ended in 1371, when factional divisions caused Bulgaria to split into three small Tsardoms. By 1396, they were subjugated by the Ottoman Empire. The Turks eliminated the Bulgarian system of nobility and ruling clergy, and Bulgaria remained an integral Turkish territory for the next 500 years."),
("zh_Hans_CN", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_MER_BULGARIA_CHAPTER_HISTORY_PARA_3", "11世纪，第一保加利亚帝国在罗斯和拜占庭的攻击下崩溃，并成为拜占庭帝国的一部分，直到1185年。然后，由阿森王朝的两兄弟--阿森和彼得领导的一次重大起义，恢复了保加利亚国家，形成了保加利亚第二帝国。在1230年代达到顶峰后，保加利亚由于一些因素而开始衰落，最明显的是它的地理位置使它容易受到来自许多方面的同时攻击和入侵。一场历史上为数不多的成功的农民起义，确立了猪倌伊瓦洛的沙皇地位。他的短暂统治对于恢复——至少是部分恢复——保加利亚国家的完整性至关重要。1300年后出现了一个相对繁荣的时期，但在1371年结束，当时的派系分裂导致保加利亚分裂成三个小沙皇国。到1396年，他们被奥斯曼帝国征服了。土耳其人消灭了保加利亚的贵族和统治神职人员制度，在接下来的500年里，保加利亚仍然是土耳其的一块完整领土。"),
("en_US", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_MER_BULGARIA_CHAPTER_HISTORY_PARA_4", "With the decline of the Ottoman Empire after 1700, signs of revival started to emerge. The Bulgarian nobility had vanished, leaving an egalitarian peasant society with a small but growing urban middle class. By the 19th century, the Bulgarian National Revival became a key component of the struggle for independence, which would culminate in the failed April uprising in 1876, which prompted the Russo-Turkish War of 1877–78 and the subsequent Liberation of Bulgaria. The initial Treaty of San Stefano was rejected by the Western Great Powers, and the following Treaty of Berlin limited Bulgaria's territories to Moesia and the region of Sofia. This left many ethnic Bulgarians out of the borders of the new state, which defined Bulgaria's militaristic approach to regional affairs and its allegiance to Germany in both World Wars."),
("zh_Hans_CN", "LOC_PEDIA_CIVILIZATIONS_PAGE_CIVILIZATION_MER_BULGARIA_CHAPTER_HISTORY_PARA_4", "随着1700年后奥斯曼帝国的衰落，复兴的迹象开始出现。保加利亚的贵族已经消失了，留下了一个平等的农民社会和一个小但不断增长的城市中产阶级。到19世纪，保加利亚民族复兴成为争取独立斗争的一个关键组成部分，这将在1876年失败的四月起义中达到顶峰，这促使了1877-78年的俄土战争和随后的保加利亚解放。最初的《圣斯特凡诺条约》被西方大国拒绝，随后的《柏林条约》将保加利亚的领土限制在莫西亚和索菲亚地区。这使得许多保加利亚族人被排除在新国家的边界之外，这决定了保加利亚对地区事务的军国主义态度以及在两次世界大战中对德国的效忠。"),
("en_US", "LOC_LOADING_INFO_LEADER_MER_SIMEON_I", "Glory upon you, Tsar Simeon I the Great, Emperor of The Bulgarians and the Romans, your conquest and expansion turned Bulgaria into an expansive empire and the centre of literature and faith for all of Slavic Europe. A true rival to Constantinople, Bulgaria's influence was felt across Europe as it's first Golden Age led it into prosperity. Scholars yearn to write of your victories one again, Tsar Simeon I, as only you can lead Bulgaria into another Golden Age, one of which will stand the test of time."),
("zh_Hans_CN", "LOC_LOADING_INFO_LEADER_MER_SIMEON_I", "荣耀归于你，沙皇西美昂一世，保加利亚人和罗马人的皇帝，你的征服和扩张使保加利亚成为一个广阔的帝国，成为整个斯拉夫欧洲的文学和信仰中心。作为君士坦丁堡的真正对手，保加利亚的影响遍及整个欧洲，因为它的第一个黄金时代使它进入了繁荣。沙皇西美昂一世，学者们渴望再次书写你的胜利，因为只有你能带领保加利亚进入另一个黄金时代，一个经得起时间考验的时代。"),
("en_US", "LOC_AGENDA_MER_SIMEON_AGENDA_NAME", "Imperial Claims"),
("zh_Hans_CN", "LOC_AGENDA_MER_SIMEON_AGENDA_NAME", "帝国宣称"),
("en_US", "LOC_AGENDA_MER_SIMEON_AGENDA_DESCRIPTION", "Likes Civilizatons with High Faith and Science output. Dislikes Civilizations on his Home Continent who are going through Golden Ages."),
("zh_Hans_CN", "LOC_AGENDA_MER_SIMEON_AGENDA_DESCRIPTION", "喜欢信仰和科学产出高的文明。不喜欢本国大陆上正在经历黄金时代的文明。"),
("en_US", "LOC_DIPLO_KUDOS_LEADER_MER_SIMEON_I_REASON_RELIGION", "(You have high faith and science)"),
("zh_Hans_CN", "LOC_DIPLO_KUDOS_LEADER_MER_SIMEON_I_REASON_RELIGION", "（您的信仰和文化产出很高）"),
("en_US", "LOC_DIPLO_MODIFIER_MER_SIMEON_I_SIMEON_AGENDA_SAME_REL_GOV", "Simeon I is pleased to see another enlightened ruler."),
("zh_Hans_CN", "LOC_DIPLO_MODIFIER_MER_SIMEON_I_SIMEON_AGENDA_SAME_REL_GOV", "西美昂很高兴看到另一个明智的领袖。"),
("en_US", "LOC_DIPLO_WARNING_LEADER_MER_SIMEON_I_REASON_NO_RELIGION", "(You are going through a Golden Age on Simeon I's Continent)"),
("zh_Hans_CN", "LOC_DIPLO_WARNING_LEADER_MER_SIMEON_I_REASON_NO_RELIGION", "（您在西美昂所处的大陆上经历黄金时代）"),
("en_US", "LOC_DIPLO_MODIFIER_MER_SIMEON_I_SIMEON_AGENDA_DIFF_REL_GOV", "Simeon I lays claim to your Empire."),
("zh_Hans_CN", "LOC_DIPLO_MODIFIER_MER_SIMEON_I_SIMEON_AGENDA_DIFF_REL_GOV", "西美昂宣称你的帝国。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SIMEON_I_TITLE", "Tsar Simeon I"),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SIMEON_I_TITLE", "沙皇西美昂一世"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SIMEON_I_SUBTITLE", "Emperor of the Bulgarians and Romans"),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SIMEON_I_SUBTITLE", "保加利亚和罗马人的皇帝"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SIMEON_I_CHAPTER_HISTORY_PARA_1", "Simeon I ruled over Bulgaria from 893 to 927, during the First Bulgarian Empire. Simeon's successful campaigns against the Byzantines, Magyars and Serbs led Bulgaria to its greatest territorial expansion ever, making it the most powerful state in contemporary Eastern Europe. His reign was also a period of unmatched cultural prosperity and enlightenment later deemed the Golden Age of Bulgarian culture."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SIMEON_I_CHAPTER_HISTORY_PARA_1", "西美昂一世于893年至927年保加利亚第一帝国时期统治了保加利亚。西美昂对拜占庭人、马加尔人和塞尔维亚人的战争胜利使保加利亚实现了有史以来最大的领土扩张，使其成为当时东欧最强大的国家。他的统治也是一个无与伦比的文化繁荣和启蒙时期，后来被视为保加利亚文化的黄金时代。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SIMEON_I_CHAPTER_HISTORY_PARA_2", "During Simeon's rule, Bulgaria spread over a territory between the Aegean, the Adriatic and the Black Sea. The newly independent Bulgarian Orthodox Church became the first new patriarchate besides the Pentarchy, and Bulgarian Glagolitic and Cyrillic translations of Christian texts spread all over the Slavic world of the time. It was at the Preslav Literary School in the 890s that the Cyrillic alphabet was developed. Halfway through his reign, Simeon assumed the title of Emperor (Tsar), having prior to that been styled Prince (Knyaz)."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SIMEON_I_CHAPTER_HISTORY_PARA_2", "在西美昂的统治期间，保加利亚的领土扩展到爱琴海、亚得里亚海和黑海之间。新独立的保加利亚东正教会成为五大牧首之外的第一个新的宗主教区，保加利亚的格拉戈里特语和西里尔语翻译的基督教文本传遍了当时的斯拉夫世界。正是在890年代的普雷斯拉夫文学学校，西里尔字母被开发出来。在位期间，西美昂获得了皇帝（沙皇）的称号，在此之前他一直被称为亲王（Knyaz）。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SIMEON_I_CHAPTER_HISTORY_PARA_3", "During Simeon's reign, Bulgaria reached its cultural apogee, becoming the literary and spiritual centre of Slavic Europe. In this respect, Simeon continued his father Boris' policy of establishing and spreading Slavic culture and attracting noted scholars and writers within Bulgaria's borders. It was in the Preslav Literary School and Ohrid Literary School, founded under Boris, that the main literary work in Bulgaria was concentrated during the reign of Simeon in the new Cyrillic alphabet which was developed there."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SIMEON_I_CHAPTER_HISTORY_PARA_3", "在西美昂统治时期，保加利亚的文化达到了顶峰，成为斯拉夫欧洲的文学和精神中心。在这方面，西美昂延续了他父亲鲍里斯的政策，在保加利亚境内传播斯拉夫文化并吸引知名学者和作家。在西米恩统治时期，保加利亚的主要文学作品都用在鲍里斯领导下建立的普雷斯拉夫文学学校和奥赫里德文学学校开发的新的西里尔字母记载。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SIMEON_I_CHAPTER_CAPSULE_BODY", "Bulgaria focuses on spreading their religion and flipping city loyalty."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SIMEON_I_CHAPTER_CAPSULE_BODY", "保加利亚专注于传播他们的宗教和转化城市的忠诚度。"),
("en_US", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SIMEON_I_CHAPTER_DETAILED_BODY", "Simeon I's Bulgaria is strongest on their home continent, spreading religious and loyalty pressure stronger then other civilizations."),
("zh_Hans_CN", "LOC_PEDIA_LEADERS_PAGE_LEADER_MER_SIMEON_I_CHAPTER_DETAILED_BODY", "西美昂一世的保加利亚在他们的本大陆十分强大，传播宗教和忠诚度压力比其他文明更强。"),
("en_US", "LOC_DIPLO_FIRST_MEET_LEADER_MER_SIMEON_I_ANY", "You look upon Tsar Simeon I the Great, Emperor of the Bulgarians and the Romans, as witnessed by the church and God! All the land around me is Bulgaria."),
("zh_Hans_CN", "LOC_DIPLO_FIRST_MEET_LEADER_MER_SIMEON_I_ANY", "我是沙皇西美昂大帝，保加利亚人和罗马人的皇帝，由教会和上帝见证！你看，我周围的所有土地都是保加利亚。"),
("en_US", "LOC_DIPLO_FIRST_MEET_VISIT_RECIPIENT_LEADER_MER_SIMEON_I_ANY", "Our Capital is a glorious center of culture and faith, where all the greatest minds can be found. Come see!"),
("zh_Hans_CN", "LOC_DIPLO_FIRST_MEET_VISIT_RECIPIENT_LEADER_MER_SIMEON_I_ANY", "我们的首都是一个繁荣的的文化和信仰中心，在这里可以找到所有最伟大的思想。来看看吧!"),
("en_US", "LOC_DIPLO_FIRST_MEET_NEAR_INITIATOR_POSITIVE_LEADER_MER_SIMEON_I_ANY", "I will bless you with my presence but this once."),
("zh_Hans_CN", "LOC_DIPLO_FIRST_MEET_NEAR_INITIATOR_POSITIVE_LEADER_MER_SIMEON_I_ANY", "我将用我的存在祝福你，但只有这一次。"),
("en_US", "LOC_DIPLO_FIRST_MEET_NO_MANS_INFO_EXCHANGE_LEADER_MER_SIMEON_I_ANY", "Let us share maps, I want to look upon my future claims."),
("zh_Hans_CN", "LOC_DIPLO_FIRST_MEET_NO_MANS_INFO_EXCHANGE_LEADER_MER_SIMEON_I_ANY", "让我们分享地图，我想看看我未来的宣称。"),
("en_US", "LOC_DIPLO_GREETING_LEADER_MER_SIMEON_I_ANY", "Back to see me again?"),
("zh_Hans_CN", "LOC_DIPLO_GREETING_LEADER_MER_SIMEON_I_ANY", "又回来见我了？"),
("en_US", "LOC_DIPLO_ACCEPT_DELEGATION_FROM_HUMAN_LEADER_MER_SIMEON_I_ANY", "What's the use in a great Empire if no one can see it? Of course you can send a delegation."),
("zh_Hans_CN", "LOC_DIPLO_ACCEPT_DELEGATION_FROM_HUMAN_LEADER_MER_SIMEON_I_ANY", "如果没有人能看到一个伟大的帝国，那么它有什么用呢？当然，你可以派一个代表团。"),
("en_US", "LOC_DIPLO_REJECT_DELEGATION_FROM_HUMAN_LEADER_MER_SIMEON_I_ANY", "Your delegation will not dirty my floor."),
("zh_Hans_CN", "LOC_DIPLO_REJECT_DELEGATION_FROM_HUMAN_LEADER_MER_SIMEON_I_ANY", "我不会让你的代表团弄脏我的房间。"),
("en_US", "LOC_DIPLO_DELEGATION_FROM_AI_LEADER_MER_SIMEON_I_ANY", "A delegation has been sent with copies of the finest works of Bulgarian literature."),
("zh_Hans_CN", "LOC_DIPLO_DELEGATION_FROM_AI_LEADER_MER_SIMEON_I_ANY", "我已派出一个代表团，带着保加利亚最优秀的文学作品的副本。"),
("en_US", "LOC_DIPLO_ACCEPT_OPEN_BORDERS_FROM_HUMAN_LEADER_MER_SIMEON_I_ANY", "This will do me fine."),
("zh_Hans_CN", "LOC_DIPLO_ACCEPT_OPEN_BORDERS_FROM_HUMAN_LEADER_MER_SIMEON_I_ANY", "这对我来说是好事。"),
("en_US", "LOC_DIPLO_REJECT_OPEN_BORDERS_FROM_HUMAN_LEADER_MER_SIMEON_I_ANY", "You make a fool of yourself, bringing such deals to my table."),
("zh_Hans_CN", "LOC_DIPLO_REJECT_OPEN_BORDERS_FROM_HUMAN_LEADER_MER_SIMEON_I_ANY", "你把这样的交易带到我的桌子上，显得自己像一个傻瓜。"),
("en_US", "LOC_DIPLO_OPEN_BORDERS_FROM_AI_LEADER_MER_SIMEON_I_ANY", "Should land not be shared? allow my troops to pass through your lands and you will be payed accordingly."),
("zh_Hans_CN", "LOC_DIPLO_OPEN_BORDERS_FROM_AI_LEADER_MER_SIMEON_I_ANY", "土地不应该被分享吗？允许我的军队通过你的土地，你将得到相应的报酬。"),
("en_US", "LOC_DIPLO_ACCEPT_DECLARE_FRIEND_FROM_HUMAN_LEADER_MER_SIMEON_I_ANY", "Of course! It's only suitable someone as great as myself would have a friend as fine as you."),
("zh_Hans_CN", "LOC_DIPLO_ACCEPT_DECLARE_FRIEND_FROM_HUMAN_LEADER_MER_SIMEON_I_ANY", "当然！像我这样伟大的人有一个像你这样优秀的朋友，才是最合适的。"),
("en_US", "LOC_DIPLO_REJECT_DECLARE_FRIEND_FROM_HUMAN_LEADER_MER_SIMEON_I_ANY", "You? a friend? Don't flatter yourself."),
("zh_Hans_CN", "LOC_DIPLO_REJECT_DECLARE_FRIEND_FROM_HUMAN_LEADER_MER_SIMEON_I_ANY", "你？“朋友”？别自以为是了。"),
("en_US", "LOC_DIPLO_DECLARE_FRIEND_FROM_AI_LEADER_MER_SIMEON_I_ANY", "I see you are a fine leader, one i can consider worthy to be my friend."),
("zh_Hans_CN", "LOC_DIPLO_DECLARE_FRIEND_FROM_AI_LEADER_MER_SIMEON_I_ANY", "我看你是一个优秀的领导者，一个我可以认为值得成为我的朋友的人。"),
("en_US", "LOC_DIPLO_ACCEPT_DECLARE_FRIEND_FROM_AI_LEADER_MER_SIMEON_I_ANY", "You truly won't regret it."),
("zh_Hans_CN", "LOC_DIPLO_ACCEPT_DECLARE_FRIEND_FROM_AI_LEADER_MER_SIMEON_I_ANY", "你不会后悔的。"),
("en_US", "LOC_DIPLO_REJECT_DECLARE_FRIEND_FROM_AI_LEADER_MER_SIMEON_I_ANY", "You must be kidding! Turning down my offer of friendship? unthinkable."),
("zh_Hans_CN", "LOC_DIPLO_REJECT_DECLARE_FRIEND_FROM_AI_LEADER_MER_SIMEON_I_ANY", "你一定是在开玩笑！拒绝我的友谊提议？ 不可思议。"),
("en_US", "LOC_DIPLO_MAKE_ALLIANCE_FROM_AI_LEADER_MER_SIMEON_I_ANY", "It would only benefit you to ally yourself with me."),
("zh_Hans_CN", "LOC_DIPLO_MAKE_ALLIANCE_FROM_AI_LEADER_MER_SIMEON_I_ANY", "与我结盟对你只有好处。"),
("en_US", "LOC_DIPLO_KUDO_EXIT_LEADER_MER_SIMEON_I_ANY", "You truly are an enlightened ruler, your culture could almost rival that of Bulgaria. But not quite."),
("zh_Hans_CN", "LOC_DIPLO_KUDO_EXIT_LEADER_MER_SIMEON_I_ANY", "你确实是一个开明的统治者，你的文化几乎可以与保加利亚相媲美。但也不尽然。"),
("en_US", "LOC_DIPLO_WARNING_EXIT_LEADER_MER_SIMEON_I_ANY", "I, Simeon I, Emperor of the Bulgarians and the Romans, lay claim to the glorious lands of your people."),
("zh_Hans_CN", "LOC_DIPLO_WARNING_EXIT_LEADER_MER_SIMEON_I_ANY", "我，西美昂，保加利亚人和罗马人的皇帝，对你们人民的光荣土地提出了宣称。"),
("en_US", "LOC_DIPLO_WARNING_TOO_MANY_TROOPS_NEAR_ME_LEADER_MER_SIMEON_I_ANY", "You must be joking! That's your army? Move it away now, save yourself."),
("zh_Hans_CN", "LOC_DIPLO_WARNING_TOO_MANY_TROOPS_NEAR_ME_LEADER_MER_SIMEON_I_ANY", "你一定是在开玩笑！那是你的军队？现在把它移开，拯救你自己。"),
("en_US", "LOC_DIPLO_ACCEPT_MAKE_DEAL_FROM_AI_LEADER_MER_SIMEON_I_ANY", "I agree."),
("zh_Hans_CN", "LOC_DIPLO_ACCEPT_MAKE_DEAL_FROM_AI_LEADER_MER_SIMEON_I_ANY", "我同意。"),
("en_US", "LOC_DIPLO_REJECT_MAKE_DEAL_FROM_AI_LEADER_MER_SIMEON_I_ANY", "I cannot."),
("zh_Hans_CN", "LOC_DIPLO_REJECT_MAKE_DEAL_FROM_AI_LEADER_MER_SIMEON_I_ANY", "不行。"),
("en_US", "LOC_DIPLO_DENOUNCE_FROM_HUMAN_LEADER_MER_SIMEON_I_ANY", "Who do you think you are? criticising the likes of me? You must have a death wish."),
("zh_Hans_CN", "LOC_DIPLO_DENOUNCE_FROM_HUMAN_LEADER_MER_SIMEON_I_ANY", "你以为你是谁，敢批评我这样的人？你一定是想求死。"),
("en_US", "LOC_DIPLO_DENOUNCE_FROM_AI_LEADER_MER_SIMEON_I_ANY", "You are not worthy of your titles, someone else would be better suited to them. Someone like me perhaps? (Denounces You)."),
("zh_Hans_CN", "LOC_DIPLO_DENOUNCE_FROM_AI_LEADER_MER_SIMEON_I_ANY", "你不配拥有你的头衔，其他人会更适合它们。也许像我这样的人？(谴责你）。"),
("en_US", "LOC_DIPLO_DENOUNCE_REASON_FROM_AI_LEADER_ANY_REASON_MER_SIMEON_I_SIMEON_AGENDA_DIFF_REL_GOV", "(You have a Golden Age on his Continent)"),
("zh_Hans_CN", "LOC_DIPLO_DENOUNCE_REASON_FROM_AI_LEADER_ANY_REASON_MER_SIMEON_I_SIMEON_AGENDA_DIFF_REL_GOV", "(你在他的大陆上经历黄金时代)"),
("en_US", "LOC_DIPLO_DECLARE_WAR_FROM_HUMAN_LEADER_MER_SIMEON_I_ANY", "You face the might of the Bulgarian Empire! Lower your swords and surrender now, it will be easier for us all."),
("zh_Hans_CN", "LOC_DIPLO_DECLARE_WAR_FROM_HUMAN_LEADER_MER_SIMEON_I_ANY", "你们面对的是保加利亚帝国的威力! 现在放下你们的剑，投降吧，这对我们双方来说都会比较简单。"),
("en_US", "LOC_DIPLO_DECLARE_WAR_FROM_AI_LEADER_MER_SIMEON_I_ANY", "Bulgaria lays claim to the lands you call yours. They will join the expansive borders of my glorious Bulgarian Empire!"),
("zh_Hans_CN", "LOC_DIPLO_DECLARE_WAR_FROM_AI_LEADER_MER_SIMEON_I_ANY", "保加利亚对你所谓的土地提出了宣称。它们将加入我的光荣的保加利亚帝国的广阔疆域!"),
("en_US", "LOC_DIPLO_MAKE_PEACE_AI_ACCEPT_DEAL_LEADER_MER_SIMEON_I_ANY", "All that wasted effort."),
("zh_Hans_CN", "LOC_DIPLO_MAKE_PEACE_AI_ACCEPT_DEAL_LEADER_MER_SIMEON_I_ANY", "所有的努力都白费了。"),
("en_US", "LOC_DIPLO_MAKE_PEACE_AI_REFUSE_DEAL_LEADER_MER_SIMEON_I_ANY", "You want it to end now? My victory is near!"),
("zh_Hans_CN", "LOC_DIPLO_MAKE_PEACE_AI_REFUSE_DEAL_LEADER_MER_SIMEON_I_ANY", "你想让它现在就结束吗？我的胜利就在眼前！"),
("en_US", "LOC_DIPLO_MAKE_PEACE_FROM_AI_LEADER_MER_SIMEON_I_ANY", "This is wasted time and effort. Let us be done with it."),
("zh_Hans_CN", "LOC_DIPLO_MAKE_PEACE_FROM_AI_LEADER_MER_SIMEON_I_ANY", "这是在浪费时间和精力。让我们做个了断吧。"),
