("zh_Hans_CN", "LOC_AGENDA_SUK_FATHER_OF_GIFTS_NAME", "礼物之父"),
("en_US", "LOC_AGENDA_SUK_FATHER_OF_GIFTS_DESCRIPTION", "Dislikes civilizations who are competing for Great People if they do not develop their cities. Admires civilizations that maintain the maximum number of districts in most cities and is home to many Great People."),
("zh_Hans_CN", "LOC_AGENDA_SUK_FATHER_OF_GIFTS_DESCRIPTION", "不喜欢不发展城市却与之竞争伟人的文明。仰慕那些把城市区域建造到上限并且拥有很多伟人的文明。"),
("en_US", "LOC_DIPLO_KUDO_LEADER_SUK_AL_HASAN_REASON_ANY", "(You have well developed cities with many Great People.)"),
("zh_Hans_CN", "LOC_DIPLO_KUDO_LEADER_SUK_AL_HASAN_REASON_ANY", "(你们有发达的城市和许多伟人。）"),
("en_US", "LOC_DIPLO_MODIFIER_SUK_FATHER_OF_GIFTS_KUDO", "Al Hasan is annoyed you are cramming your great people into underdeveloped cities"),
("zh_Hans_CN", "LOC_DIPLO_MODIFIER_SUK_FATHER_OF_GIFTS_KUDO", "哈桑对你把你的伟人塞进不发达的城市很是愤怒。"),
("en_US", "LOC_DIPLO_WARNING_LEADER_SUK_AL_HASAN_REASON_ANY", "(You are competing for Great People, but have ignored city development.)"),
